                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500 mt-1"
                    />
                    <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                </div>

                <button 
                    onClick={handleRestart} 
