                                                    key={role}
                                                    onClick={() => setDraftRole(role)}
                                                    className={`w-12 h-12 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                    title={role}
                                                >
                                                    <span className="text-lg mb-0.5 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    <span className="text-[8px] font-bold uppercase">{role.substring(0,3)}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* HP Pool */}
                            <div className="flex flex-col justify-center gap-1 w-20 shrink-0">
                                <label className="text-[9px] text-slate-500 font-bold uppercase text-center">HP Pool</label>
                                <input 
                                    type="number" 
                                    value={hpInput} 
                                    onChange={e => setHpInput(parseInt(e.target.value))} 
                                    className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500"
                                />
                            </div>
                        </div>
                    </div>

                    {/* ZONE 3: MAP OPS */}
                    <div className="w-40 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">Map Operations</div>
                        <div className="grid grid-cols-2 gap-2">
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">WIDTH</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                            </div>
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">HEIGHT</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                            </div>
                        </div>
                        <div className="flex gap-2 mt-auto">
                            <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">REBUILD</button>
                            <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">CLEAR</button>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector */}
          {/* Resizer */}
          {!isShowcaseMode && (
            <div 
                className="w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize flex items-center justify-center shrink-0 transition-colors z-30 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel */}
          <div 
            className={`flex flex-col shrink-0 z-20 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}`}
            style={{ width: isShowcaseMode ? 0 : sidebarWidth }}
          >
            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.6) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    <div className="h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* FLOATING HUD (Top Center) */}
      <div className={`absolute top-6 left-1/2 -translate-x-1/2 z-40 transition-all duration-500 ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-6 py-2 rounded-full flex items-center gap-4 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50">
                <button 
                    onClick={togglePlay} 
                    disabled={winner !== null}
                    className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                >
                    {isPlaying ? '⏸' : '▶'}
                </button>

                <div className="flex flex-col items-center w-32">
                    <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">Time Scale</span>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500 mt-1"
                    />
                    <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                </div>

                <button 
                    onClick={handleRestart} 
                    disabled={!isPlaying && winner === null}
                    className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                    title="Reset Round"
                >
                    ↺
                </button>

                <div className="w-px h-8 bg-slate-700 mx-2"></div>

                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="text-xs font-bold text-slate-500 hover:text-purple-400 transition-colors"
                >
                    📺 TV MODE
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-20 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">Deployment Error</span>
                        <span className="text-xs">Deploy units for BOTH factions to engage.</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-transparent to-black/40 pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">Battlefield Simulation Engine v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>Initialize Command</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">Sim Rate</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden">

          {/* LEFT COLUMN: Canvas + Dock */}
          <div className="flex-1 flex flex-col relative min-w-0">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} // Needs wrap
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                <div className={`h-40 bg-slate-950 border-t border-slate-800 shrink-0 z-30 flex transition-all duration-500 ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* ZONE 1: COMMAND TOOLS */}
                    <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">Command Tools</div>
                        <div className="grid grid-cols-2 gap-2 flex-1">
                            <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                <span className="text-lg">⌖</span>
                                <span className="text-[9px]">SELECT</span>
                            </button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                <span className="text-lg">❌</span>
                                <span className="text-[9px]">DELETE</span>
                            </button>
                            <button onClick={() => setTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                <span className="flex items-center gap-2">
                                    <span className="text-lg">🧱</span>
                                    <span className="text-[9px]">OBSTACLE</span>
                                </span>
                            </button>
                        </div>
                        {tool === ToolType.OBSTACLE && (
                            <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}
                    </div>

                    {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                    <div className="flex-1 p-3 flex flex-col gap-2 relative">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                            <span>Unit Deployment</span>
                            <span className="text-slate-700 font-mono">UNITS: {unitCount}</span>
                        </div>

                        <div className="flex gap-4 h-full">
                            {/* Team Selectors (Sets Tool) */}
                            <div className="flex flex-col gap-2 w-32 shrink-0">
                                <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">BLUE</span>
                                    <span className="text-lg">🔵</span>
                                </button>
                                <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">RED</span>
                                    <span className="text-lg">🔴</span>
                                </button>
                            </div>

                            {/* Mode & Draft Config */}
                            <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2">
                                <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        🎲 RANDOM
                                    </button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        📝 DRAFT
                                    </button>
                                </div>

                                <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                    {spawnMode === 'RANDOM' ? (
                                        <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                            <span className="text-2xl mb-1">🎲</span>
                                            <span>RANDOM CLASS</span>
                                        </div>
                                    ) : (
                                        <div className="flex gap-2 w-full justify-center">
                                            {Object.values(Role).map(role => (
                                                <button 
                                                    key={role}
                                                    onClick={() => setDraftRole(role)}
                                                    className={`w-12 h-12 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                    title={role}
                                                >
                                                    <span className="text-lg mb-0.5 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    <span className="text-[8px] font-bold uppercase">{role.substring(0,3)}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* HP Pool */}
                            <div className="flex flex-col justify-center gap-1 w-20 shrink-0">
                                <label className="text-[9px] text-slate-500 font-bold uppercase text-center">HP Pool</label>
                                <input 
                                    type="number" 
                                    value={hpInput} 
                                    onChange={e => setHpInput(parseInt(e.target.value))} 
                                    className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500"
                                />
                            </div>
                        </div>
                    </div>

                    {/* ZONE 3: MAP OPS */}
                    <div className="w-40 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">Map Operations</div>
                        <div className="grid grid-cols-2 gap-2">
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">WIDTH</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                            </div>
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">HEIGHT</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                            </div>
                        </div>
                        <div className="flex gap-2 mt-auto">
                            <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">REBUILD</button>
                            <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">CLEAR</button>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector */}
          {/* Resizer */}
          {!isShowcaseMode && (
            <div 
                className="w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize flex items-center justify-center shrink-0 transition-colors z-30 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel */}
          <div 
            className={`flex flex-col shrink-0 z-20 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}`}
            style={{ width: isShowcaseMode ? 0 : sidebarWidth }}
          >
            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

// Added missing React and hook imports
import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; // New: Specific type
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT'; // New
    draftRole: Role; // New
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); // Adjusted default zoom
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // Interaction State
    const draggedAgentRef = useRef<Agent | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isDraggingUnit = useRef(false);

    const isPanning = useRef(false);
    const isPainting = useRef(false); // New: Track if painting
    const lastPaintHex = useRef<string>(""); // Prevent spamming same tile

    const pointerDownStart = useRef<{x: number, y: number} | null>(null);
    const pendingAction = useRef<boolean>(false); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                if (engine.agents.length === 0) {
                    centerCamera();
                }
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                const highlight = draggedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return {
                x: x - rect.left,
                y: y - rect.top
            };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;

            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 30 && Math.abs(dy) < 50) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const handleActionAt = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;

            let agent: Agent | null = null;

            if (tool === ToolType.ADD_BLUE) {
                agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            } else if (tool === ToolType.ADD_RED) {
                agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            } else if (tool === ToolType.OBSTACLE) {
                if (engine.getAgentAt(h.q, h.r)) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
            } else if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (engine.getAgentAt(h.q, h.r)) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
            }

            // DRAFT MODE LOGIC
            // If in Draft Mode, force the selected role and re-roll skills
            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;

                // 1. Re-roll skills compatible with the new role
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];

                // 2. Persist new state
                agent.saveState();

                // 3. Reset to apply stats from UNIT_DB based on the new role
                agent.reset(engine.mapConfig);
            }
        };

        // SHARED DOWN
        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pointerDownStart.current = { x: sx, y: sy };

            if (button === 2) {
                isPanning.current = true;
                pendingAction.current = false;
                return;
            }

            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent && tool === ToolType.SELECT) {
                pendingAction.current = false;
                onSelect(hitAgent);
                if (!engine.isRunning) {
                    draggedAgentRef.current = hitAgent;
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                    isDraggingUnit.current = true;
                }
                return;
            }

            const h = getHexFromCoords(sx, sy);
            const gridAgent = engine.getAgentAt(h.q, h.r);
            if (gridAgent && tool === ToolType.SELECT && !hitAgent) {
                 pendingAction.current = false;
                 onSelect(gridAgent);
                 if (!engine.isRunning) {
                    draggedAgentRef.current = gridAgent;
                    dragStartHex.current = { q: gridAgent.q, r: gridAgent.r };
                    isDraggingUnit.current = true;
                 }
                 return;
            }

            pendingAction.current = true;
            isPanning.current = false;

            if (!engine.isRunning && tool !== ToolType.SELECT) {
                isPainting.current = true;
                lastPaintHex.current = ""; 
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }
        };

        // SHARED MOVE
        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            if (tool === ToolType.SELECT && !isDraggingUnit.current && !isPanning.current) {
                const hit = getHitAgentFromCoords(sx, sy);
                if (cvs) cvs.style.cursor = hit ? 'pointer' : 'default';
            } else if (isDraggingUnit.current && cvs) {
                cvs.style.cursor = 'grabbing';
            }

            if (isPanning.current) {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedAgentRef.current.px = wPos.x;
                draggedAgentRef.current.py = wPos.y;
                return;
            }

            if (isPainting.current && !engine.isRunning) {
                if (engine.isValid(h.q, h.r)) {
                    handleActionAt(h);
                }
            }

            if (pendingAction.current && pointerDownStart.current && !isPainting.current) {
                const dist = Math.sqrt((sx - pointerDownStart.current.x)**2 + (sy - pointerDownStart.current.y)**2);
                if (dist > 5) {
                    pendingAction.current = false;
                    isPanning.current = true;
                    camera.current.x -= dx / camera.current.zoom;
                    camera.current.y -= dy / camera.current.zoom;
                }
            }
        };

        // SHARED UP
        const handleUp = (sx: number, sy: number) => {
            isPainting.current = false;
            lastPaintHex.current = "";

            if (isPanning.current) {
                isPanning.current = false;
                pointerDownStart.current = null;
                return;
            }

            if (isDraggingUnit.current && draggedAgentRef.current) {
                const h = getHexFromCoords(sx, sy);
                const agent = draggedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }

                draggedAgentRef.current = null;
                dragStartHex.current = null;
                isDraggingUnit.current = false;
                onSelect(agent);
                if (cvs) cvs.style.cursor = 'default';
                return;
            }

            if (pendingAction.current) {
                pendingAction.current = false;
                if (tool === ToolType.SELECT) {
                    const hitAgent = getHitAgentFromCoords(sx, sy);
                    if (hitAgent) onSelect(hitAgent);
                    else onSelect(null);
                } 
            }
            pointerDownStart.current = null;
        };

        // Mouse Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        // Touch Listeners
        const onTouchStart = (e: TouchEvent) => {
            e.preventDefault();
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // When 2 fingers down, cancel single finger drag/selection
                pendingAction.current = false;
                isDraggingUnit.current = false;
                draggedAgentRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            e.preventDefault();
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        // Mobile touch events
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner ${tool === ToolType.SELECT ? 'cursor-default' : 'cursor-crosshair'}`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import React, { useEffect, useState, useRef, memo } from 'react';
import { Agent } from '../engine/game';
import { BTNode } from '../engine/behaviorTree';
import { Team, Skill, LogEntry, NodeState, Role } from '../types';
import { AssetManager } from '../engine/assets';

interface InspectorProps {
    agent: Agent | null;
    engine: any;
    logs: LogEntry[]; 
    db: Skill[];
    onHoverSkill?: (skill: Skill | null) => void;
}

// --- VISUALIZATION COMPONENTS ---

const TreeNode: React.FC<{ node: BTNode, version: number, now: number }> = ({ node, version, now }) => {
    // Logic for Visual Persistence
    const timeDiff = now - node.lastRunTime;
    let visualState: NodeState | null = node.status;
    let isFading = false;
    let opacity = 1.0;

    if (!visualState && node.lastResult) {
        if (timeDiff < 1000) { 
            visualState = node.lastResult;
            isFading = true;
            if (timeDiff > 200) opacity = 0.7;
            if (timeDiff > 500) opacity = 0.4;
        }
    }

    const statusStyle = (s: NodeState | null) => {
        switch (s) {
            case NodeState.RUNNING: return "border-amber-500 bg-amber-950/80 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.5)] ring-2 ring-amber-500 animate-pulse-glow z-10 scale-105";
            case NodeState.SUCCESS: return "border-emerald-500 bg-emerald-950/80 text-emerald-100 shadow-[0_0_5px_rgba(16,185,129,0.4)]";
            case NodeState.FAILURE: return "border-red-800 bg-red-950/80 text-red-200 opacity-80";
            default: return "border-slate-600 bg-slate-800 text-slate-400";
        }
    };

    const typeSymbol = (t: string) => {
        if(t === '?') return <span className="text-purple-400 font-bold mr-2 text-lg">?</span>;
        if(t === '->') return <span className="text-blue-400 font-bold mr-2 text-lg">➜</span>;
        if(t === 'COND') return <span className="text-pink-400 text-sm mr-2">◆</span>;
        if(t === 'ACT') return <span className="text-yellow-400 text-sm mr-2">⚡</span>;
        return null;
    }

    return (
        <div className="flex flex-col items-center">
            <div 
                className={`flex items-center px-4 py-3 rounded-md border-2 text-sm font-mono font-bold transition-all duration-100 cursor-default select-none shadow-md min-w-[120px] justify-center ${statusStyle(visualState)}`}
                style={{ opacity: opacity }}
            >
                {typeSymbol(node.type)}
                <span className="whitespace-nowrap truncate max-w-[180px]">{node.n}</span>
            </div>
            {node.c && node.c.length > 0 && (
                <div className="flex flex-col items-center">
                    <div className={`w-0.5 h-6 ${isFading ? 'bg-slate-600/50' : 'bg-slate-500'}`}></div>
                    <div className="flex items-start gap-4">
                        {node.c.map((child, idx) => (
                            <div key={child.id} className="flex flex-col items-center relative">
                                {/* Connector Lines */}
                                <div className="absolute top-0 left-0 w-full h-6 -mt-6 pointer-events-none">
                                     {node.c.length > 1 && (
                                         <>
                                            {idx === 0 && <div className="absolute right-0 top-0 w-1/2 h-0.5 bg-slate-500 translate-y-6"></div>}
                                            {idx === node.c.length - 1 && <div className="absolute left-0 top-0 w-1/2 h-0.5 bg-slate-500 translate-y-6"></div>}
                                            {idx > 0 && idx < node.c.length - 1 && <div className="absolute left-0 top-0 w-full h-0.5 bg-slate-500 translate-y-6"></div>}
                                         </>
                                     )}
                                     <div className="absolute left-1/2 top-0 w-0.5 h-6 bg-slate-500 translate-y-6 -translate-x-1/2"></div>
                                </div>

                                <div className="pt-6">
                                    <TreeNode node={child} version={version} now={now} />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

const SkillIcon: React.FC<{ skill: Skill | null, className?: string }> = ({ skill, className }) => {
    const sizeClass = (className?.includes('w-') && className?.includes('h-')) ? '' : 'w-10 h-10';
    if (!skill || !skill.visual) return <div className={`rounded bg-slate-800 border-2 border-slate-700 flex items-center justify-center text-xs text-slate-500 ${sizeClass} ${className || ''}`}>∅</div>;
    const iconUrl = AssetManager.getSkillIcon(skill.visual, skill.color).toDataURL();
    return <img src={iconUrl} className={`rounded bg-slate-900 border-2 border-slate-600 shadow-md ${sizeClass} ${className || ''}`} alt={skill.visual} />;
};

const LogItem = memo(({ log }: { log: LogEntry }) => (
    <div className="mb-2 border-b border-slate-800 pb-2 last:border-0 hover:bg-slate-900/50 transition-colors text-xs sm:text-sm font-mono flex items-start">
        <span className="text-slate-500 w-14 shrink-0 opacity-70">[{log.time}s]</span>
        <div className="flex-1 min-w-0 break-words">
            <span className={`font-bold mr-2 ${log.team === Team.BLUE ? 'text-blue-400' : (log.team === Team.RED ? 'text-red-400' : 'text-slate-400')}`}>
                {log.agentId ? `${log.agentId}` : 'SYSTEM'}
            </span>
            <span className="text-slate-300 mr-2 font-semibold">{log.action}</span>
            {log.target !== '自身' && log.target && (
                <><span className="text-slate-600 mx-1">➜</span><span className="text-amber-300 mr-2">{log.target}</span></>
            )}
            <span className="text-slate-400 block sm:inline opacity-90">{log.detail}</span>
        </div>
    </div>
));

// --- MAIN COMPONENT ---

const InspectorPanel: React.FC<InspectorProps> = ({ agent, engine, db, onHoverSkill }) => {
    const [tab, setTab] = useState<'INSPECTOR' | 'LOG' | 'DB'>('INSPECTOR');
    const [inspectorSubTab, setInspectorSubTab] = useState<'STATUS' | 'AI'>('STATUS');
    const [version, setVersion] = useState(0); 
    const [btFps, setBtFps] = useState(20); 
    const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);

    // DB Filtering
    const [dbTypeTab, setDbTypeTab] = useState<'ALL' | 'BASIC' | 'ACTIVE' | 'ULT'>('ALL');
    const [dbRoleFilter, setDbRoleFilter] = useState<Role | 'ALL'>('ALL');

    // BT Interaction
    const [btScale, setBtScale] = useState(0.8);
    const [btPos, setBtPos] = useState({x: 0, y: 20});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const isDraggingBT = useRef(false);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Refresh Loop
    useEffect(() => {
        if (tab !== 'INSPECTOR' || !agent) return;
        const interval = setInterval(() => setVersion(n => n + 1), 1000 / btFps);
        return () => clearInterval(interval);
    }, [tab, agent, btFps]);

    // Log Polling
    useEffect(() => {
        if (tab === 'LOG') {
            const interval = setInterval(() => {
                if (engine.logs.length !== localLogs.length) setLocalLogs(engine.logs.slice(-100));
            }, 200);
            return () => clearInterval(interval);
        }
    }, [tab, engine, localLogs.length]);

    // Auto-Center AI Tree
    useEffect(() => {
        if (tab === 'INSPECTOR' && inspectorSubTab === 'AI' && agent?.bt) {
            const timer = setTimeout(() => {
                // Keep default or recenter logic simple
            }, 100); 
            return () => clearTimeout(timer);
        }
    }, [agent?.id, tab, inspectorSubTab]);

    // BT Interaction Handlers
    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + (e.deltaY > 0 ? -0.1 : 0.1))));
    };
    const handleBtMouseDown = () => { isDraggingBT.current = true; };
    const handleBtMouseMove = (e: React.MouseEvent) => {
        if (isDraggingBT.current) setBtPos(p => ({ x: p.x + e.movementX, y: p.y + e.movementY }));
    };
    const handleBtMouseUp = () => { isDraggingBT.current = false; };

    // Touch Logic
    const handleBtTouchStart = (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
            lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            isDraggingBT.current = true;
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            isDraggingBT.current = false;
        }
    };
    const handleBtTouchMove = (e: React.TouchEvent) => {
        if (e.touches.length === 1 && lastTouchPos.current && isDraggingBT.current) {
            const touch = e.touches[0];
            const dx = touch.clientX - lastTouchPos.current.x;
            const dy = touch.clientY - lastTouchPos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastTouchPos.current = { x: touch.clientX, y: touch.clientY };
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            const currentDist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            if (lastPinchDist.current > 0) {
                const delta = currentDist - lastPinchDist.current;
                setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta * 0.005)));
            }
            lastPinchDist.current = currentDist;
        }
    };
    const handleBtTouchEnd = () => {
        isDraggingBT.current = false;
        lastTouchPos.current = null;
        lastPinchDist.current = 0;
    };

    const setSkill = (idx: number, id: string) => {
        if (agent) { agent.skillIds[idx] = id || null; setVersion(n => n + 1); }
    };
    const setRole = (r: string) => { if (agent) { agent.role = r as Role; setVersion(n => n + 1); } };
    const updateSkill = (field: keyof Skill, value: any) => {
        const skill = db.find(s => s.id === selectedSkillId);
        if (skill) { (skill as any)[field] = value; setVersion(n => n + 1); }
    };
    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    const selectedSkill = db.find(s => s.id === selectedSkillId);
    const filteredSkills = db.filter(s => {
        if (dbTypeTab !== 'ALL' && s.tag !== dbTypeTab) return false;
        if (dbRoleFilter !== 'ALL' && s.role !== dbRoleFilter) return false;
        return true;
    });

    const getRoleColor = (r: Role) => {
        switch(r) {
            case Role.TANK: return 'text-amber-400 border-amber-500/50';
            case Role.WARRIOR: return 'text-red-400 border-red-500/50';
            case Role.RANGER: return 'text-emerald-400 border-emerald-500/50';
            case Role.MAGE: return 'text-blue-400 border-blue-500/50';
            case Role.SUPPORT: return 'text-cyan-400 border-cyan-500/50';
            default: return 'text-slate-400 border-slate-500/50';
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-950 text-slate-200 w-full select-none border-l border-slate-800">
            {/* MAIN TAB NAV */}
            <div className="flex border-b border-slate-800 bg-slate-900/50 shrink-0">
                {['INSPECTOR', 'LOG', 'DB'].map(t => (
                    <button 
                        key={t} 
                        onClick={() => setTab(t as any)} 
                        className={`flex-1 py-4 text-sm font-bold tracking-wider transition-all ${tab === t ? 'text-cyan-400 border-b-2 border-cyan-500 bg-slate-800' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-900'}`}
                    >
                        {t === 'INSPECTOR' ? 'UNIT DATA' : (t === 'LOG' ? 'BATTLE LOG' : 'DATABASE')}
                    </button>
                ))}
            </div>

            <div className="flex-1 overflow-hidden flex flex-col min-h-0 relative">
                {tab === 'INSPECTOR' && (!agent ? (
                    <div className="flex-1 flex flex-col items-center justify-center text-slate-600 p-8 text-center">
                        <div className="text-6xl mb-4 opacity-20">⌖</div>
                        <div className="text-lg font-bold">NO UNIT SELECTED</div>
                        <div className="text-sm">Select a unit on the battlefield to inspect.</div>
                    </div>
                ) : (
                    <div className="flex flex-col h-full">
                         {/* UNIT HEADER */}
                        <div className="p-4 border-b border-slate-800 shrink-0 bg-slate-900 z-20 shadow-lg">
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <div className="flex items-center gap-3 mb-1">
                                        <div className={`w-4 h-4 rounded-full ${agent.team === Team.BLUE ? 'bg-blue-500 shadow-[0_0_10px_#3b82f6]' : 'bg-red-500 shadow-[0_0_10px_#ef4444]'}`}></div>
                                        <span className="font-mono text-2xl font-bold text-white tracking-tight">{agent.id}</span>
                                    </div>
                                    <div className="text-slate-400 text-xs font-mono flex gap-3">
                                        <span>POS: <span className="text-slate-200">{agent.q}, {agent.r}</span></span>
                                        <span>|</span>
                                        <span>HP: <span className={agent.hp < agent.maxHp * 0.3 ? 'text-red-500 animate-pulse' : 'text-green-400'}>{Math.ceil(agent.hp)}</span>/{agent.maxHp}</span>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <div className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-1">CURRENT ACTION</div>
                                    <div className="bg-slate-800 border border-slate-600 px-3 py-1 rounded text-cyan-300 font-bold text-sm shadow-inner min-w-[100px] text-center">
                                        {agent.btStatus}
                                    </div>
                                </div>
                            </div>

                            {/* SUB TABS */}
                            <div className="flex bg-slate-950 rounded p-1 gap-1 border border-slate-800">
                                <button onClick={() => setInspectorSubTab('STATUS')} className={`flex-1 py-2 text-xs rounded font-bold transition-all ${inspectorSubTab === 'STATUS' ? 'bg-slate-800 text-cyan-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:bg-slate-900'}`}>STATUS & SKILLS</button>
                                <button onClick={() => setInspectorSubTab('AI')} className={`flex-1 py-2 text-xs rounded font-bold transition-all ${inspectorSubTab === 'AI' ? 'bg-slate-800 text-amber-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:bg-slate-900'}`}>BEHAVIOR TREE</button>
                            </div>
                        </div>

                        {/* TAB CONTENT: STATUS */}
                        {inspectorSubTab === 'STATUS' && (
                            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-6">
                                {/* STAT BLOCK */}
                                <div className="space-y-4">
                                    <div>
                                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">Role Classification</label>
                                        <select 
                                            className={`tactical-input h-12 w-full text-lg font-bold bg-slate-900 border-2 ${getRoleColor(agent.role)}`}
                                            value={agent.role} 
                                            onChange={(e) => setRole(e.target.value)}
                                        >
                                            {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                                        </select>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-slate-900 p-3 rounded border border-slate-800">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">Health Pool</label>
                                            <input 
                                                type="number" 
                                                className="tactical-input h-12 w-full text-2xl text-center text-green-400 font-mono bg-black/30 border-green-900/50 focus:border-green-500"
                                                value={Math.round(agent.maxHp)} 
                                                onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; setVersion(n => n + 1); }} 
                                            />
                                            <div className="h-1 bg-slate-800 mt-2 rounded overflow-hidden">
                                                <div className="h-full bg-green-500" style={{width: `${(agent.hp/agent.maxHp)*100}%`}}></div>
                                            </div>
                                        </div>
                                        <div className="bg-slate-900 p-3 rounded border border-slate-800">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">Mana Capacity</label>
                                            <input 
                                                type="number" 
                                                className="tactical-input h-12 w-full text-2xl text-center text-blue-400 font-mono bg-black/30 border-blue-900/50 focus:border-blue-500"
                                                value={Math.round(agent.maxMp)} 
                                                onChange={(e) => { agent.maxMp = parseInt(e.target.value); setVersion(n => n + 1); }} 
                                            />
                                            <div className="h-1 bg-slate-800 mt-2 rounded overflow-hidden">
                                                <div className="h-full bg-blue-500" style={{width: `${(agent.mp/agent.maxMp)*100}%`}}></div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="border-t border-slate-800 pt-4">
                                    <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Active Skillset</div>
                                    <div className="space-y-4">
                                        {['ULT', 'ACTIVE', 'BASIC'].map((tag, i) => {
                                            const currentSkillId = agent.skillIds[i];
                                            const currentSkill = db.find(s => s.id === currentSkillId);

                                            // Available skills Logic
                                            const availableSkills = db.filter(s => s.tag === tag);
                                            const skillsByRole: Record<string, Skill[]> = {};
                                            availableSkills.forEach(s => {
                                                if(!skillsByRole[s.role]) skillsByRole[s.role] = [];
                                                skillsByRole[s.role].push(s);
                                            });
                                            const roleOrder = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

                                            return (
                                                <div key={i} className="bg-slate-900 rounded-sm border border-slate-700 shadow-md transition-all hover:border-slate-500" onMouseEnter={() => onHoverSkill && onHoverSkill(currentSkill || null)} onMouseLeave={() => onHoverSkill && onHoverSkill(null)}>
                                                    <div className="flex items-center gap-3 p-3 bg-slate-800/50 border-b border-slate-800">
                                                        <SkillIcon skill={currentSkill} className="w-12 h-12" />
                                                        <div className="flex-1">
                                                            <div className="text-[10px] font-bold text-slate-500 mb-1 flex justify-between">
                                                                <span>{tag} SLOT</span>
                                                                {currentSkill && <span className="text-slate-400 font-mono">ID: {currentSkill.id}</span>}
                                                            </div>
                                                            <select 
                                                                className={`tactical-input h-10 w-full text-sm font-bold appearance-none cursor-pointer ${!currentSkillId ? 'text-slate-500' : 'text-slate-200'}`}
                                                                value={agent.skillIds[i] || ""} 
                                                                onChange={(e) => setSkill(i, e.target.value)}
                                                            >
                                                                <option value="">-- EMPTY SLOT --</option>
                                                                {roleOrder.map(role => {
                                                                    const skills = skillsByRole[role];
                                                                    if (!skills || skills.length === 0) return null;
                                                                    return (
                                                                        <optgroup key={role} label={role} className="bg-slate-900 text-slate-400">
                                                                            {skills.map(s => (
                                                                                <option key={s.id} value={s.id} className="text-white">
                                                                                    {s.name} {s.team !== undefined ? (s.team === Team.BLUE ? '🔵' : '🔴') : ''}
                                                                                </option>
                                                                            ))}
                                                                        </optgroup>
                                                                    );
                                                                })}
                                                            </select>
                                                        </div>
                                                    </div>

                                                    {currentSkill && (
                                                        <div className="p-3 text-sm">
                                                            <div className="text-slate-400 italic mb-3 leading-relaxed border-l-2 border-slate-700 pl-3">
                                                                "{currentSkill.desc}"
                                                            </div>
                                                            <div className="grid grid-cols-4 gap-2 text-xs font-mono text-slate-300">
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">PWR</div>
                                                                    <div className="font-bold text-base">{currentSkill.power}</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">CD</div>
                                                                    <div className="font-bold text-base">{currentSkill.cd}s</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">COST</div>
                                                                    <div className="font-bold text-base text-blue-400">{currentSkill.cost}</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">RNG</div>
                                                                    <div className="font-bold text-base">{currentSkill.range}</div>
                                                                </div>
                                                            </div>
                                                            {(currentSkill.ccType || currentSkill.effectType) && (
                                                                <div className="mt-3 pt-2 border-t border-slate-800 flex gap-2 flex-wrap">
                                                                    {currentSkill.ccType && <span className="px-2 py-1 bg-amber-900/30 text-amber-400 border border-amber-900/50 rounded text-xs font-bold">{currentSkill.ccType}</span>}
                                                                    {currentSkill.effectType && <span className="px-2 py-1 bg-purple-900/30 text-purple-400 border border-purple-900/50 rounded text-xs font-bold">{currentSkill.effectType}</span>}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* TAB CONTENT: AI */}
                        {inspectorSubTab === 'AI' && (
                             <div 
                                className="flex-1 bg-[#0f1115] relative overflow-hidden flex flex-col min-h-0 cursor-grab active:cursor-grabbing" 
                                ref={btContainerRef} 
                                onWheel={handleBtWheel} 
                                onMouseDown={handleBtMouseDown} 
                                onMouseMove={handleBtMouseMove} 
                                onMouseUp={handleBtMouseUp} 
                                onMouseLeave={handleBtMouseUp}
                                onTouchStart={handleBtTouchStart}
                                onTouchMove={handleBtTouchMove}
                                onTouchEnd={handleBtTouchEnd}
                                style={{touchAction: 'none'}}
                             >
                                <div className="absolute top-4 left-4 z-10 glass-panel px-3 py-2 flex items-center gap-3">
                                    <div className="text-xs font-bold text-slate-400 uppercase">Refresh Rate</div>
                                    <input type="range" min="1" max="60" value={btFps} onChange={e => setBtFps(parseInt(e.target.value))} className="w-24 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
                                    <span className="text-cyan-400 font-mono text-xs w-6 text-right">{btFps}</span>
                                </div>

                                <div className="absolute top-4 right-4 z-10 glass-panel px-3 py-2 text-xs font-mono text-slate-400">
                                    ZOOM: {Math.round(btScale * 100)}%
                                </div>

                                <div className="absolute w-full h-full flex justify-center items-start pt-20 origin-top-center will-change-transform" 
                                     style={{
                                         transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                                         backgroundImage: 'radial-gradient(#334155 1px, transparent 1px)', 
                                         backgroundSize: '32px 32px'
                                     }}>
                                    <div id="bt-root-content" className="inline-block px-12 pb-12">
                                        {agent.bt && <TreeNode node={agent.bt} version={version} now={Date.now()} />}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                ))}

                {tab === 'LOG' && (
                    <div className="flex flex-col h-full bg-slate-900">
                        <div className="p-3 border-b border-slate-800 bg-slate-950 flex justify-between items-center shrink-0">
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Live Feed (Last 100)</span>
                            <button onClick={downloadLogs} className="tactical-btn text-xs">
                                EXPORT JSON
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 font-mono">
                            {localLogs.slice().reverse().map(log => (
                                <LogItem key={log.id} log={log} />
                            ))}
                            {localLogs.length === 0 && <div className="text-slate-600 text-center mt-20 italic">No combat data recorded</div>}
                        </div>
                    </div>
                )}

                {tab === 'DB' && (
                    <div className="flex flex-col h-full bg-slate-900">
                        <div className="p-3 border-b border-slate-800 bg-slate-950 shrink-0 space-y-3">
                            <div className="flex bg-slate-900 rounded p-1 gap-1 border border-slate-800">
                                {['ALL', 'BASIC', 'ACTIVE', 'ULT'].map(t => (
                                    <button 
                                        key={t}
                                        onClick={() => setDbTypeTab(t as any)} 
                                        className={`flex-1 py-2 text-xs rounded font-bold transition-all ${dbTypeTab === t ? 'bg-slate-800 text-cyan-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:text-slate-300'}`}
                                    >
                                        {t}
                                    </button>
                                ))}
                            </div>

                            <select 
                                className="tactical-input w-full h-10 text-sm"
                                value={dbRoleFilter}
                                onChange={(e) => setDbRoleFilter(e.target.value as any)}
                            >
                                <option value="ALL">FILTER ROLE: ALL</option>
                                {Object.values(Role).map(r => <option key={r} value={r}>ROLE: {r}</option>)}
                            </select>
                        </div>

                        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">
                            {filteredSkills.map(skill => (
                                <div key={skill.id} className={`border rounded transition-all duration-200 ${selectedSkillId === skill.id ? 'border-cyan-500 bg-slate-800 shadow-lg' : 'border-slate-800 bg-slate-900 hover:border-slate-600'}`}>
                                    <div 
                                        className="flex items-center gap-3 p-3 cursor-pointer"
                                        onClick={() => setSelectedSkillId(skill.id === selectedSkillId ? null : skill.id)}
                                    >
                                        <SkillIcon skill={skill} />
                                        <div className="flex-1 min-w-0">
                                            <div className="font-bold text-sm text-slate-200">{skill.name}</div>
                                            <div className="text-xs text-slate-500 flex gap-2 items-center mt-1">
                                                <span className="font-mono font-bold">{skill.role}</span>
                                                <span className="w-1 h-1 bg-slate-600 rounded-full"></span>
                                                <span className={`${skill.tag === 'ULT' ? 'text-purple-400' : (skill.tag === 'ACTIVE' ? 'text-blue-400' : 'text-slate-400')} font-bold`}>{skill.tag}</span>
                                            </div>
                                        </div>
                                        <div className="text-slate-600 text-lg">
                                            {selectedSkillId === skill.id ? '−' : '+'}
                                        </div>
                                    </div>

                                    {selectedSkillId === skill.id && (
                                        <div className="p-4 border-t border-slate-700 bg-black/20">
                                            <div className="grid grid-cols-2 gap-4 mb-4">
                                                <div className="space-y-1">
                                                    <label className="text-xs font-bold text-slate-500">POWER</label>
                                                    <input type="number" className="tactical-input w-full h-10" value={skill.power} onChange={e => updateSkill('power', parseInt(e.target.value))} />
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-xs font-bold text-slate-500">COOLDOWN</label>
                                                    <input type="number" className="tactical-input w-full h-10" value={skill.cd} step="0.5" onChange={e => updateSkill('cd', parseFloat(e.target.value))} />
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-xs font-bold text-slate-500">COST</label>
                                                    <input type="number" className="tactical-input w-full h-10" value={skill.cost} onChange={e => updateSkill('cost', parseInt(e.target.value))} />
                                                </div>
                                                <div className="space-y-1">
                                                    <label className="text-xs font-bold text-slate-500">RANGE</label>
                                                    <input type="number" className="tactical-input w-full h-10" value={skill.range} onChange={e => updateSkill('range', parseInt(e.target.value))} />
                                                </div>
                                            </div>
                                            <div className="space-y-1">
                                                <label className="text-xs font-bold text-slate-500">DESCRIPTION</label>
                                                <textarea 
                                                    className="tactical-input w-full p-2 h-20 text-sm resize-none"
                                                    value={skill.desc || ""}
                                                    onChange={e => updateSkill('desc', e.target.value)}
                                                />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default InspectorPanel;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.6) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    <div className="h-screen w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* FLOATING HUD (Top Center) - Responsive Layout */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-40 transition-all duration-500 w-[95%] max-w-[600px] ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-between gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg">

                {/* Control Group */}
                <div className="flex items-center gap-3">
                    <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
                </div>

                <div className="hidden md:block w-px h-8 bg-slate-700"></div>

                {/* Speed Control - Collapsible on tiny screens */}
                <div className="flex-1 flex flex-col items-center min-w-[120px]">
                    <div className="flex items-center justify-between w-full mb-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                        <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                    </div>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                    />
                </div>

                <div className="hidden md:block w-px h-8 bg-slate-700"></div>

                {/* Mode Switch */}
                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all flex items-center gap-2"
                >
                    <span>📺</span>
                    <span className="hidden sm:inline">展示模式</span>
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-transparent to-black/40 pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in px-4">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>初始化指揮系統</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden">

          {/* LEFT COLUMN: Canvas + Dock */}
          <div className="flex-1 flex flex-col relative min-w-0">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} // Needs wrap
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                <div className={`h-40 bg-slate-950 border-t border-slate-800 shrink-0 z-30 flex overflow-x-auto transition-all duration-500 ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* ZONE 1: COMMAND TOOLS */}
                    <div className="w-40 md:w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">指揮工具</div>
                        <div className="grid grid-cols-2 gap-2 flex-1">
                            <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                <span className="text-lg">⌖</span>
                                <span className="text-[9px]">選取</span>
                            </button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                <span className="text-lg">❌</span>
                                <span className="text-[9px]">移除</span>
                            </button>
                            <button onClick={() => setTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                <span className="flex items-center gap-2">
                                    <span className="text-lg">🧱</span>
                                    <span className="text-[9px]">地形</span>
                                </span>
                            </button>
                        </div>
                        {tool === ToolType.OBSTACLE && (
                            <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}
                    </div>

                    {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                    <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                            <span>單位部署</span>
                            <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                        </div>

                        <div className="flex gap-4 h-full">
                            {/* Team Selectors (Sets Tool) */}
                            <div className="flex flex-col gap-2 w-28 shrink-0">
                                <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">藍隊</span>
                                    <span className="text-lg">🔵</span>
                                </button>
                                <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">紅隊</span>
                                    <span className="text-lg">🔴</span>
                                </button>
                            </div>

                            {/* Mode & Draft Config */}
                            <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        🎲 隨機
                                    </button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        📝 自選
                                    </button>
                                </div>

                                <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                    {spawnMode === 'RANDOM' ? (
                                        <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                            <span className="text-2xl mb-1">🎲</span>
                                            <span>隨機職階</span>
                                        </div>
                                    ) : (
                                        <div className="flex gap-1.5 w-full justify-center">
                                            {Object.values(Role).map(role => (
                                                <button 
                                                    key={role}
                                                    onClick={() => setDraftRole(role)}
                                                    className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                    title={role}
                                                >
                                                    <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* HP Pool */}
                            <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                <input 
                                    type="number" 
                                    value={hpInput} 
                                    onChange={e => setHpInput(parseInt(e.target.value))} 
                                    className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                />
                            </div>
                        </div>
                    </div>

                    {/* ZONE 3: MAP OPS */}
                    <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                        <div className="grid grid-cols-2 gap-2">
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">寬度</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                            </div>
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">高度</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                            </div>
                        </div>
                        <div className="flex gap-2 mt-auto">
                            <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                            <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空</button>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector */}
          {/* Resizer */}
          {!isShowcaseMode && (
            <div 
                className="w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize flex items-center justify-center shrink-0 transition-colors z-30 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel */}
          <div 
            className={`flex flex-col shrink-0 z-20 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}`}
            style={{ width: isShowcaseMode ? 0 : sidebarWidth }}
          >
            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useState, useRef, memo } from 'react';
import { Agent } from '../engine/game';
