                                                                    {currentSkill.effectType && <span className="px-2 py-1 bg-purple-900/30 text-purple-400 border border-purple-900/50 rounded text-xs font-bold">{currentSkill.effectType}</span>}
                                                                </div>
                                                            )}
                                                        </div>
