                                                </div>
                                            </div>
                                            <div className="space-y-1">
                                                <label className="text-xs font-bold text-slate-500">描述</label>
                                                <textarea 
                                                    className="tactical-input w-full p-2 h-20 text-sm resize-none"
                                                    value={skill.desc || ""}
                                                    onChange={e => updateSkill('desc', e.target.value)}
                                                />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

