import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { UNIT_DB } from "../data/units";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS } from "../constants";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; // Vertical mobility tier
    public weight: number = 1; // Knockback resistance
    public movementType: MovementType = MovementType.GROUND;

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Status Effects (Managed by StatusSystem)
    public stunTimer: number = 0;
    public banishTimer: number = 0;
    public silenceTimer: number = 0;
    public banished: boolean = false;
    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public animTimer: number = 0; 
    public hitFlashTimer: number = 0;

    // Physics (Enhanced for 3D bounce)
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
            this.animTimer = 0;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.banishTimer = 0;
        this.silenceTimer = 0;
        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
    }
}

export class GameEngine {
    public agents: Agent[] = [];

    // Delegated to MapSystem
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }

    // Delegated to CombatSystem (Single Source of Truth)
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];

    public isRunning: boolean = false;
    public timeScale: number = 1.0;
    public battleTime: number = 0;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public onWin?: (team: Team) => void;

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    // Subsystems
    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();

        this.map.randomizeEnvironment(this);
    }

    // --- Passthroughs ---

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }

    // Updated to support Paint Mode
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    // Updated to support flying logic check
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // --- Core Logic Control ---

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
        }

        this.agentMap.clear();

        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); // Use AI System
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });
        this.combat.projectiles = []; // Clear projectiles via combat system
        this.battleTime = 0;
        this.play();
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.combat.projectiles = []; // Clear projectiles via combat system
        this.logs = [];
        this.directorTargetId = null;
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
    }

    // --- Main Game Loop ---

    tick(dt: number) {
        if (!this.isRunning) return;

        // Memory Optimization: Reuse array instead of reallocation
        this.events.length = 0;

        this.updateDirector(dt); // AI Director Logic

        // Win Condition Check
        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }
        if (blue === 0 && red > 0) { this.stop(); this.onWin?.(Team.RED); }
        else if (red === 0 && blue > 0) { this.stop(); this.onWin?.(Team.BLUE); }

        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            // Physics delegated to MovementSystem
            this.movement.updatePhysics(a, dt, this);

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // --- DELEGATED SYSTEMS ---
            this.status.update(a, dt, this);

            // Movement Update
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            // AI Update
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    // --- Loop Sub-Methods ---

    private updateDirector(dt: number) {
        this.directorTimer -= dt;

        // Ensure current target is still valid
        const current = this.agents.find(a => a.id === this.directorTargetId);
        if (!current || current.hp <= 0) {
            this.directorTimer = -1; // Force switch
        }

        if (this.directorTimer <= 0) {
            // Pick new target logic (simplified for brevity, logic remains same)
            const alive = this.agents.filter(a => a.hp > 0);
            if (alive.length > 0) {
                const ultCasters = alive.filter(a => a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT');
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0;
                     return;
                }

                this.directorTargetId = alive[Math.floor(Math.random() * alive.length)].id;
                this.directorTimer = 3.0;
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 

            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    // Rich Logging Overhaul
    log(agent: Agent | null, typeOrAction: LogActionType | string, actionNameOrTarget: string | null, detailOrTargetInfo: string, legacyDetail?: string) {
        const time = this.battleTime.toFixed(1);

        let actionType: LogActionType = 'SYSTEM';
        let actionName = 'Action';
        let targetInfo = '';
        let detail = '';
        let color = '#94a3b8'; // default slate

        // Handle Legacy Calls (from StatusSystem, AgentManager, etc.)
        // Old: log(agent, actionString, targetId, detailString)
        const isLegacy = !this.isLogActionType(typeOrAction);

        if (isLegacy) {
            const rawAction = typeOrAction as string;
            actionName = rawAction;
            targetInfo = actionNameOrTarget || '';
            detail = detailOrTargetInfo;

            // Map Legacy strings to Types
            if (rawAction === '死亡') { actionType = 'DEATH'; color = '#71717a'; }
            else if (rawAction === '放逐結束') { actionType = 'CC'; color = '#c084fc'; }
            else if (rawAction === '中斷') { actionType = 'CC'; color = '#facc15'; }
            else if (rawAction === '命中') { actionType = 'HIT'; color = '#ef4444'; }
            else { actionType = 'SYSTEM'; }
        } else {
            // New Rich Signature
            // log(agent, type, actionName, targetInfo, detail)
            actionType = typeOrAction as LogActionType;
            actionName = actionNameOrTarget || '';
            targetInfo = detailOrTargetInfo || '';
            detail = legacyDetail || '';

            switch(actionType) {
                case 'MOVE': color = '#3b82f6'; break; // Blue
                case 'CAST': color = '#f59e0b'; break; // Amber
                case 'HIT': color = '#ef4444'; break; // Red
                case 'HEAL': color = '#22c55e'; break; // Green
                case 'DECISION': color = '#a855f7'; break; // Purple
                case 'DEATH': color = '#71717a'; break; // Zinc
                case 'CC': color = '#facc15'; break; // Yellow
                default: color = '#94a3b8'; break;
            }
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10), // Tick
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: actionType,
            actionName: actionName,
            targetInfo: targetInfo,
            detail: detail,
            visualColor: color,
            // Legacy compat
            action: actionName,
            target: targetInfo,
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }

    private isLogActionType(val: any): val is LogActionType {
        return ['MOVE','CAST','HIT','DECISION','DEATH','SYSTEM','HEAL','CC'].includes(val);
    }
}

import { Agent, GameEngine } from "../game";
import { BTNode, Selector, Sequence, Condition, Action } from "../behaviorTree";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";

export class AISystem {

    public buildAI(a: Agent, engine: GameEngine): BTNode {
        const root = new Selector("Root");

        root.add(new Sequence("Dead")
            .add(new Condition("IsDead", (ctx: Agent) => ctx.hp <= 0))
            .add(new Action("Wait", (ctx: Agent) => { ctx.btStatus = "死亡"; return NodeState.RUNNING; }))
        );

        const cc = new Selector("CC");
        cc.add(new Sequence("Stunned")
            .add(new Condition("IsStun", (ctx: Agent) => ctx.stunTimer > 0))
            .add(new Action("Wait", (ctx: Agent) => { ctx.btStatus = "暈眩"; return NodeState.RUNNING; }))
        );
        cc.add(new Sequence("Banished")
            .add(new Condition("IsBanish", (ctx: Agent) => ctx.banishTimer > 0))
            .add(new Action("Wait", (ctx: Agent) => { ctx.btStatus = "放逐"; return NodeState.RUNNING; }))
        );
        root.add(cc);

        const combat = new Sequence("Combat");

        combat.add(new Condition("Target", (ctx: Agent) => {
            engine.movement.updateTarget(ctx, engine);
            return ctx.target !== null;
        }));

        const skillSelector = new Selector("Skills");
        [0, 1, 2].forEach(i => {
            const seq = new Sequence(`Slot${i}`);
            seq.add(new Condition("Ready", (ctx: Agent) => 
                !!ctx.skills[i] && 
                ctx.curCDs[i] <= 0 && 
                ctx.mp >= ctx.skills[i]!.cost && 
                ctx.castingSkillIdx === -1 &&
                ctx.silenceTimer <= 0
            ));

            const act = new Selector("Act");

            // Priority: Calculate Best Spot, Move There, Then Cast
            act.add(new Sequence("CastOptimal")
                .add(new Condition("FindOpt", (ctx: Agent) => {
                    const result = engine.movement.calculateOptimalTarget(ctx, ctx.skills[i]!, engine);

                    if (result.targetAgent) {
                        ctx.target = result.targetAgent;
                        ctx.targetHex = null;
                        // Range check with Height Bonus using the shared MovementSystem
                        const effRange = engine.movement.getEffectiveRange(ctx, ctx.target.q, ctx.target.r, ctx.skills[i]!.range, engine);
                        return HexUtils.dist(ctx, result.targetAgent) <= effRange;
                    } 
                    else if (result.targetHex) {
                        ctx.target = null;
                        ctx.targetHex = result.targetHex;
                        // Valid ground target found, proceed to execution flow
                        return true; 
                    }
                    return false;
                }))
                .add(new Selector("ExecuteOrMove")
                    // Sub-Selector: Try Cast -> Fail -> Move to Spot
                    .add(new Sequence("TryCast")
                        .add(new Condition("InRange", (ctx: Agent) => {
                            // Re-verify range just before casting (targets move)
                            let tQ = 0, tR = 0;
                            if (ctx.targetHex) { tQ = ctx.targetHex.q; tR = ctx.targetHex.r; }
                            else if (ctx.target) { tQ = ctx.target.q; tR = ctx.target.r; }
                            else return false;

                            const effRange = engine.movement.getEffectiveRange(ctx, tQ, tR, ctx.skills[i]!.range, engine);
                            const dist = ctx.targetHex ? HexUtils.dist(ctx, ctx.targetHex) : HexUtils.dist(ctx, ctx.target!);

                            return dist <= effRange;
                        }))
                        .add(new Action("Do", (ctx: Agent) => {
                            engine.log(ctx, 'DECISION', 'AI決策', '施放技能', `決定使用 ${ctx.skills[i]!.name}`);
                            return engine.performCast(ctx, i);
                        }))
                    )
                    .add(new Action("MoveToSpot", (ctx: Agent) => {
                        const skill = ctx.skills[i]!;
                        // Charge Logic: If skill is melee/short-range (<= 2), burst speed to close gap
                        const speedMult = skill.range <= 2 ? 2.5 : 1.0;
                        if (ctx.targetHex) {
                            if (!ctx.isMoving) engine.log(ctx, 'DECISION', 'AI決策', '戰術移動', `前往最佳施法位置 (${ctx.targetHex.q},${ctx.targetHex.r})`);
                            return engine.movement.moveAgentToHex(ctx, ctx.targetHex, skill.range, engine, speedMult);
                        }
                        // Fallback for moving towards agent if targetHex wasn't set but targetAgent was
                        if (ctx.target) {
                             if (!ctx.isMoving) engine.log(ctx, 'DECISION', 'AI決策', '戰術移動', `接近目標 ${ctx.target.id}`);
                             return engine.movement.moveAgent(ctx, ctx.target, skill.range, engine, speedMult);
                        }
                        return NodeState.FAILURE;
                    }))
                )
            );

            // Default Fallback: Just chase nearest enemy if no optimal move found
            act.add(new Action("MoveGeneral", (ctx: Agent) => {
                engine.movement.updateTarget(ctx, engine); 
                if (!ctx.target) return NodeState.FAILURE;

                const skill = ctx.skills[i]!;
                const speedMult = skill.range <= 2 ? 2.5 : 1.0;

                // Stickiness check: If we are already moving towards a valid target, don't switch unless much closer
                if (!ctx.isMoving) engine.log(ctx, 'DECISION', 'AI決策', '追擊', `追擊最近目標 ${ctx.target.id}`);
                return engine.movement.moveAgent(ctx, ctx.target, skill.range, engine, speedMult);
            }));

            skillSelector.add(seq.add(act));
        });

        combat.add(skillSelector);

        combat.add(new Action("Idle", (ctx: Agent) => { 
            ctx.btStatus = ctx.silenceTimer > 0 ? "沉默" : "待機"; 
            return NodeState.SUCCESS; 
        }));

        return root.add(combat);
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { AnimState, Hex, NodeState, MovementType } from "../../types";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";

// Constants extracted from game.ts
const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 
const STACKING_RESOLUTION_FORCE = 5;

const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
// INCREASED DAMPING: Makes units stop snappier, reducing "floating" feel
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 

const GRAVITY = 2000; 

export class MovementSystem {
    // Pathfinding Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    // Optimization: Reuse Stacking Map to reduce GC
    private _stackingMap = new Map<number, Agent[]>();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Vertical Dynamics (Gravity vs Flight)
        if (a.movementType === MovementType.FLYING && !isDead) {
            // Flying Unit Logic
            if (a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH') {
                // CRASH STATE: Apply Gravity immediately
                a.physics.vz -= GRAVITY * dt;
            } else {
                // HOVER STATE: Bob around a target altitude
                // Increased to 90 to visually clear walls (80px)
                const hoverHeight = 90; 
                const hoverFreq = 3;
                const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 10;

                // Soft spring to maintain height
                const dz = targetZ - a.physics.z;
                a.physics.vz += dz * 5 * dt;
                a.physics.vz *= 0.95; // Drag to stop oscillation
            }
        } else {
            // Ground Unit Logic
            if (isDead || isAirborne) {
                a.physics.vz -= GRAVITY * dt;
            }
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Vertical interpolation logic can be handled in UnitRenderSystem, 
        // here we mostly care about X/Y transition for logic updates

        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);
            engine.log(a, 'MOVE', '移動', `(${nextHex.q},${nextHex.r})`, '抵達目的地');

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range (With Height Bonus)
        const effRange = this.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        if (HexUtils.dist(a, targetHex) <= effRange) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.findPath(a, targetHex.q, targetHex.r, r, false, engine);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.findPath(a, targetHex.q, targetHex.r, r, true, engine); // true = ignoreUnits
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            // Updated to pass movementType to isBlocked
            if (engine.isBlocked(next.q, next.r, a.id, a.movementType)) {
                // We know where we WANT to go, but it's blocked right now.
                // Instead of failing (which causes AI jitter/wandering), we WAIT.
                // This simulates "queueing" behind the frontline.
                a.setAnim(AnimState.COMBAT_IDLE);

                // Only log block once to avoid spam
                if (Math.random() < 0.05) {
                    engine.log(a, 'MOVE', '移動', `(${next.q},${next.r})`, '路徑被阻擋，等待中');
                }

                // Return RUNNING to keep the AI node active, preventing re-calculation jitter
                return NodeState.RUNNING; 
            }

            engine.log(a, 'MOVE', '移動', `前往 (${next.q},${next.r})`, '開始移動');
            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        // We don't necessarily need to step ON their tile.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this._stackingMap.clear();
        const map = this._stackingMap;

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine, agent.id, agent.movementType));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }

    // =========================================================================================
    // 🗺️ PATHFINDING (A* / Multi-Layer BFS)
    // =========================================================================================

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range (using Height Bonus)
        const effRange = this.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);
            const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);

            // SUCCESS CONDITION: Inside Range? (Check height for this specific tile)
            const currentEffRange = this.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine);
            if (HexUtils.dist(currentHex, targetHex) <= currentEffRange) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check
                // NEW: Flying Logic Check
                if (engine.map.hasObstacleHash(nextH)) {
                    // We need to check obstacle type
                    const obstacleTypeId = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(nextH)));
                    const obstacleDef = OBSTACLE_DB[obstacleTypeId || 'WALL'];

                    if (startAgent.movementType === MovementType.FLYING) {
                        // Flying units only blocked by specific "Sky Blockers" (like tall pillars)
                        if (obstacleDef?.blocksFlying) continue;
                    } else {
                        // Ground units blocked by standard "blocksMovement"
                        if (obstacleDef?.blocksMovement) continue;
                    }
                }

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                // Flying units IGNORE terrain height traversal costs
                if (startAgent.movementType !== MovementType.FLYING) {
                    const nextHexCoord = HexUtils.unhash(nextH);
                    const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                    const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                    // Allow climb/drop if deltaH <= Jump Height (in pixels)
                    // Using max(1, jump) to ensure at least 1 block can be traversed by default
                    const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                    if (deltaH > maxClimb) {
                        continue; // Too steep!
                    }
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }

    // =========================================================================================
    // 🎯 TARGETING & TACTICS
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            // Exact check happens inside the loop using effective range.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT } from "../../../constants";

const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0) {
            const skillName = a.skills[a.castingSkillIdx]?.name || '技能';

            // Log interrupt only once when timer is just set? 
            // Since this runs every frame, we rely on state transition handling in GameEngine or StatusSystem.
            // But if we want to log the interruption moment, we should do it where the CC is applied.
            // Here we just cancel the cast.

            // To prevent log spam, we just cancel silently here as the CC application logs the cause.
            // But we can add a specific "Interrupted" log if we track state change.
            if (a.castTimer > 0) {
                 engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');
            }

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution Branch: Projectile vs Instant
            if (s.projectileSpeed && s.projectileSpeed > 0) {
                 engine.combat.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: { q: number, r: number } | null = null;

        // 1. Identify Targets
        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            // Single Target - Verify Height-Aware Range
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                const actualDist = HexUtils.dist(source, source.target);

                if (actualDist <= effectiveRange) {
                    targets = [source.target];
                }
            }
        }

        const origin = {x: source.px, y: source.py};

        // 2. VISUAL ENFORCEMENT: Beam/Tracer for Ranged Instant Attacks
        // If range > 1, we MUST draw a line. If range == 1, it's melee (SMASH/SLASH) handles itself via hit effect.
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({
                    type: 'VISUAL_BEAM',
                    pos: { x: t.px, y: t.py }, // Beam End Point
                    sourceId: source.id,
                    targetId: t.id,
                    skill: skill,
                    color: skill.color
                });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        // 3. Melee / Self / Miss Visuals
        if (targets.length === 0 && skill.type === 'AOE' && centerHex) {
             // Missed/Ground Hit logic if needed, but CAST_FINISH handles the ground circle/smash visual
        }

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;
        const oldHp = Math.ceil(target.hp);

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            const originX = origin ? origin.x : source.px;
            const originY = origin ? origin.y : source.py;
            let dx = target.px - originX;
            let dy = target.py - originY;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len > 0) {
                dx /= len; dy /= len;
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += dx * impactForce;
                target.physics.vy += dy * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        const newHp = Math.ceil(target.hp);

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        // EMIT EVENT
        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        // RICH LOG: Hit
        engine.log(
            source, 
            rawDmg < 0 ? 'HEAL' : 'HIT', 
            skill.name, 
            target.id, 
            `${rawDmg > 0 ? '造成傷害' : '回復生命'} ${Math.abs(rawDmg)} (HP: ${oldHp} -> ${newHp})`
        );

        // RICH LOG: Kill
        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    if (!engine.isValid(bestN.q, bestN.r)) break; 
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; 

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) break; 
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) break; 

                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.9) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
