// --- VISUALIZATION COMPONENTS ---

const TreeNode: React.FC<{ node: BTNode, version: number, now: number }> = ({ node, version, now }) => {
    // Logic for Visual Persistence
    const timeDiff = now - node.lastRunTime;
    let visualState: NodeState | null = node.status;
    let isFading = false;
    let opacity = 1.0;

    if (!visualState && node.lastResult) {
        if (timeDiff < 1000) { 
            visualState = node.lastResult;
            isFading = true;
            if (timeDiff > 200) opacity = 0.7;
            if (timeDiff > 500) opacity = 0.4;
        }
    }

    const statusStyle = (s: NodeState | null) => {
        switch (s) {
            case NodeState.RUNNING: return "border-amber-500 bg-amber-950/80 text-amber-100 shadow-[0_0_15px_rgba(245,158,11,0.5)] ring-2 ring-amber-500 animate-pulse-glow z-10 scale-105";
            case NodeState.SUCCESS: return "border-emerald-500 bg-emerald-950/80 text-emerald-100 shadow-[0_0_5px_rgba(16,185,129,0.4)]";
            case NodeState.FAILURE: return "border-red-800 bg-red-950/80 text-red-200 opacity-80";
            default: return "border-slate-600 bg-slate-800 text-slate-400";
        }
    };

    const typeSymbol = (t: string) => {
        if(t === '?') return <span className="text-purple-400 font-bold mr-2 text-lg">?</span>;
        if(t === '->') return <span className="text-blue-400 font-bold mr-2 text-lg">➜</span>;
        if(t === 'COND') return <span className="text-pink-400 text-sm mr-2">◆</span>;
        if(t === 'ACT') return <span className="text-yellow-400 text-sm mr-2">⚡</span>;
        return null;
    }

    return (
        <div className="flex flex-col items-center">
            <div 
                className={`flex items-center px-4 py-3 rounded-md border-2 text-sm font-mono font-bold transition-all duration-100 cursor-default select-none shadow-md min-w-[120px] justify-center ${statusStyle(visualState)}`}
                style={{ opacity: opacity }}
            >
                {typeSymbol(node.type)}
                <span className="whitespace-nowrap truncate max-w-[180px]">{node.n}</span>
            </div>
            {node.c && node.c.length > 0 && (
                <div className="flex flex-col items-center">
                    <div className={`w-0.5 h-6 ${isFading ? 'bg-slate-600/50' : 'bg-slate-500'}`}></div>
                    <div className="flex items-start gap-4">
                        {node.c.map((child, idx) => (
                            <div key={child.id} className="flex flex-col items-center relative">
                                {/* Connector Lines */}
                                <div className="absolute top-0 left-0 w-full h-6 -mt-6 pointer-events-none">
                                     {node.c.length > 1 && (
                                         <>
                                            {idx === 0 && <div className="absolute right-0 top-0 w-1/2 h-0.5 bg-slate-500 translate-y-6"></div>}
                                            {idx === node.c.length - 1 && <div className="absolute left-0 top-0 w-1/2 h-0.5 bg-slate-500 translate-y-6"></div>}
                                            {idx > 0 && idx < node.c.length - 1 && <div className="absolute left-0 top-0 w-full h-0.5 bg-slate-500 translate-y-6"></div>}
                                         </>
                                     )}
                                     <div className="absolute left-1/2 top-0 w-0.5 h-6 bg-slate-500 translate-y-6 -translate-x-1/2"></div>
                                </div>

                                <div className="pt-6">
                                    <TreeNode node={child} version={version} now={now} />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};

const SkillIcon: React.FC<{ skill: Skill | null, className?: string }> = ({ skill, className }) => {
    const sizeClass = (className?.includes('w-') && className?.includes('h-')) ? '' : 'w-10 h-10';
    if (!skill || !skill.visual) return <div className={`rounded bg-slate-800 border-2 border-slate-700 flex items-center justify-center text-xs text-slate-500 ${sizeClass} ${className || ''}`}>∅</div>;
    const iconUrl = AssetManager.getSkillIcon(skill.visual, skill.color).toDataURL();
    return <img src={iconUrl} className={`rounded bg-slate-900 border-2 border-slate-600 shadow-md ${sizeClass} ${className || ''}`} alt={skill.visual} />;
};

const LogItem = memo(({ log }: { log: LogEntry }) => (
    <div className="mb-2 border-b border-slate-800 pb-2 last:border-0 hover:bg-slate-900/50 transition-colors text-xs sm:text-sm font-mono flex items-start">
        <span className="text-slate-500 w-14 shrink-0 opacity-70">[{log.time}s]</span>
        <div className="flex-1 min-w-0 break-words">
            <span className={`font-bold mr-2 ${log.team === Team.BLUE ? 'text-blue-400' : (log.team === Team.RED ? 'text-red-400' : 'text-slate-400')}`}>
                {log.agentId ? `${log.agentId}` : '系統'}
            </span>
            <span className="text-slate-300 mr-2 font-semibold">{log.action}</span>
            {log.target !== '自身' && log.target && (
                <><span className="text-slate-600 mx-1">➜</span><span className="text-amber-300 mr-2">{log.target}</span></>
            )}
            <span className="text-slate-400 block sm:inline opacity-90">{log.detail}</span>
        </div>
    </div>
));

// --- MAIN COMPONENT ---

const InspectorPanel: React.FC<InspectorProps> = ({ agent, engine, db, onHoverSkill }) => {
    const [tab, setTab] = useState<'INSPECTOR' | 'LOG' | 'DB'>('INSPECTOR');
    const [inspectorSubTab, setInspectorSubTab] = useState<'STATUS' | 'AI'>('STATUS');
    const [version, setVersion] = useState(0); 
    const [btFps, setBtFps] = useState(20); 
    const [selectedSkillId, setSelectedSkillId] = useState<string | null>(null);
    const [localLogs, setLocalLogs] = useState<LogEntry[]>([]);

    // DB Filtering
    const [dbTypeTab, setDbTypeTab] = useState<'ALL' | 'BASIC' | 'ACTIVE' | 'ULT'>('ALL');
    const [dbRoleFilter, setDbRoleFilter] = useState<Role | 'ALL'>('ALL');

    // BT Interaction
    const [btScale, setBtScale] = useState(0.8);
    const [btPos, setBtPos] = useState({x: 0, y: 20});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const isDraggingBT = useRef(false);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Refresh Loop
    useEffect(() => {
        if (tab !== 'INSPECTOR' || !agent) return;
        const interval = setInterval(() => setVersion(n => n + 1), 1000 / btFps);
        return () => clearInterval(interval);
    }, [tab, agent, btFps]);

    // Log Polling
    useEffect(() => {
        if (tab === 'LOG') {
            const interval = setInterval(() => {
                if (engine.logs.length !== localLogs.length) setLocalLogs(engine.logs.slice(-100));
            }, 200);
            return () => clearInterval(interval);
        }
    }, [tab, engine, localLogs.length]);

    // Auto-Center AI Tree
    useEffect(() => {
        if (tab === 'INSPECTOR' && inspectorSubTab === 'AI' && agent?.bt) {
            const timer = setTimeout(() => {
                // Keep default or recenter logic simple
            }, 100); 
            return () => clearTimeout(timer);
        }
    }, [agent?.id, tab, inspectorSubTab]);

    // BT Interaction Handlers
    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + (e.deltaY > 0 ? -0.1 : 0.1))));
    };
    const handleBtMouseDown = () => { isDraggingBT.current = true; };
    const handleBtMouseMove = (e: React.MouseEvent) => {
        if (isDraggingBT.current) setBtPos(p => ({ x: p.x + e.movementX, y: p.y + e.movementY }));
    };
    const handleBtMouseUp = () => { isDraggingBT.current = false; };

    // Touch Logic
    const handleBtTouchStart = (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
            lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            isDraggingBT.current = true;
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            isDraggingBT.current = false;
        }
    };
    const handleBtTouchMove = (e: React.TouchEvent) => {
        if (e.touches.length === 1 && lastTouchPos.current && isDraggingBT.current) {
            const touch = e.touches[0];
            const dx = touch.clientX - lastTouchPos.current.x;
            const dy = touch.clientY - lastTouchPos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastTouchPos.current = { x: touch.clientX, y: touch.clientY };
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            const currentDist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            if (lastPinchDist.current > 0) {
                const delta = currentDist - lastPinchDist.current;
                setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta * 0.005)));
            }
            lastPinchDist.current = currentDist;
        }
    };
    const handleBtTouchEnd = () => {
        isDraggingBT.current = false;
        lastTouchPos.current = null;
        lastPinchDist.current = 0;
    };

    const setSkill = (idx: number, id: string) => {
        if (agent) { agent.skillIds[idx] = id || null; setVersion(n => n + 1); }
    };
    const setRole = (r: string) => { if (agent) { agent.role = r as Role; setVersion(n => n + 1); } };
    const updateSkill = (field: keyof Skill, value: any) => {
        const skill = db.find(s => s.id === selectedSkillId);
        if (skill) { 
            // Type safety helper
            if (field === 'team') {
                if (value === 'ANY') (skill as any)[field] = undefined;
                else if (value === 'BLUE') (skill as any)[field] = Team.BLUE;
                else if (value === 'RED') (skill as any)[field] = Team.RED;
            } else {
                (skill as any)[field] = value; 
            }
            setVersion(n => n + 1); 
        }
    };
    const downloadLogs = () => {
        const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(engine.logs, null, 2));
        const anchor = document.createElement('a');
        anchor.setAttribute("href", dataStr);
        anchor.setAttribute("download", `battle_logs_${Date.now()}.json`);
        anchor.click();
    };

    const selectedSkill = db.find(s => s.id === selectedSkillId);
    const filteredSkills = db.filter(s => {
        if (dbTypeTab !== 'ALL' && s.tag !== dbTypeTab) return false;
        if (dbRoleFilter !== 'ALL' && s.role !== dbRoleFilter) return false;
        return true;
    });

    const getRoleColor = (r: Role) => {
        switch(r) {
            case Role.TANK: return 'text-amber-400 border-amber-500/50';
            case Role.WARRIOR: return 'text-red-400 border-red-500/50';
            case Role.RANGER: return 'text-emerald-400 border-emerald-500/50';
            case Role.MAGE: return 'text-blue-400 border-blue-500/50';
            case Role.SUPPORT: return 'text-cyan-400 border-cyan-500/50';
            default: return 'text-slate-400 border-slate-500/50';
        }
    };

    return (
        <div className="flex flex-col h-full bg-slate-950 text-slate-200 w-full select-none border-l border-slate-800">
            {/* MAIN TAB NAV */}
            <div className="flex border-b border-slate-800 bg-slate-900/50 shrink-0">
                {['INSPECTOR', 'LOG', 'DB'].map(t => (
                    <button 
                        key={t} 
                        onClick={() => setTab(t as any)} 
                        className={`flex-1 py-4 text-sm font-bold tracking-wider transition-all ${tab === t ? 'text-cyan-400 border-b-2 border-cyan-500 bg-slate-800' : 'text-slate-500 hover:text-slate-300 hover:bg-slate-900'}`}
                    >
                        {t === 'INSPECTOR' ? '單位監控' : (t === 'LOG' ? '戰況紀錄' : '技能資料庫')}
                    </button>
                ))}
            </div>

            <div className="flex-1 overflow-hidden flex flex-col min-h-0 relative">
                {tab === 'INSPECTOR' && (!agent ? (
                    <div className="flex-1 flex flex-col items-center justify-center text-slate-600 p-8 text-center">
                        <div className="text-6xl mb-4 opacity-20">⌖</div>
                        <div className="text-lg font-bold">未選取單位</div>
                        <div className="text-sm">請在地圖上選取單位以查看詳情。</div>
                    </div>
                ) : (
                    <div className="flex flex-col h-full">
                         {/* UNIT HEADER */}
                        <div className="p-4 pt-6 border-b border-slate-800 shrink-0 bg-slate-900 z-20 shadow-lg">
                            <div className="flex justify-between items-start mb-4">
                                <div>
                                    <div className="flex items-center gap-3 mb-1">
                                        <div className={`w-4 h-4 rounded-full ${agent.team === Team.BLUE ? 'bg-blue-500 shadow-[0_0_10px_#3b82f6]' : 'bg-red-500 shadow-[0_0_10px_#ef4444]'}`}></div>
                                        <span className="font-mono text-2xl font-bold text-white tracking-tight">{agent.id}</span>
                                    </div>
                                    <div className="text-slate-400 text-xs font-mono flex gap-3">
                                        <span>位置: <span className="text-slate-200">{agent.q}, {agent.r}</span></span>
                                        <span>|</span>
                                        <span>HP: <span className={agent.hp < agent.maxHp * 0.3 ? 'text-red-500 animate-pulse' : 'text-green-400'}>{Math.ceil(agent.hp)}</span>/{agent.maxHp}</span>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <div className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-1">當前行動</div>
                                    <div className="bg-slate-800 border border-slate-600 px-3 py-1 rounded text-cyan-300 font-bold text-sm shadow-inner min-w-[100px] text-center">
                                        {agent.btStatus}
                                    </div>
                                </div>
                            </div>

                            {/* SUB TABS */}
                            <div className="flex bg-slate-950 rounded p-1 gap-1 border border-slate-800">
                                <button onClick={() => setInspectorSubTab('STATUS')} className={`flex-1 py-2 text-xs rounded font-bold transition-all ${inspectorSubTab === 'STATUS' ? 'bg-slate-800 text-cyan-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:bg-slate-900'}`}>狀態數值</button>
                                <button onClick={() => setInspectorSubTab('AI')} className={`flex-1 py-2 text-xs rounded font-bold transition-all ${inspectorSubTab === 'AI' ? 'bg-slate-800 text-amber-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:bg-slate-900'}`}>AI 行為</button>
                            </div>
                        </div>

                        {/* TAB CONTENT: STATUS */}
                        {inspectorSubTab === 'STATUS' && (
                            <div className="flex-1 overflow-y-auto custom-scrollbar p-4 pb-24 space-y-6">
                                {/* STAT BLOCK */}
                                <div className="space-y-4">
                                    <div>
                                        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">職階分類</label>
                                        <select 
                                            className={`tactical-input h-12 w-full text-lg font-bold bg-slate-900 border-2 ${getRoleColor(agent.role)}`}
                                            value={agent.role} 
                                            onChange={(e) => setRole(e.target.value)}
                                        >
                                            {Object.values(Role).map(r => <option key={r} value={r}>{ROLE_MAP[r]}</option>)}
                                        </select>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="bg-slate-900 p-3 rounded border border-slate-800">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">生命值</label>
                                            <input 
                                                type="number" 
                                                className="tactical-input h-12 w-full text-2xl text-center text-green-400 font-mono bg-black/30 border-green-900/50 focus:border-green-500"
                                                value={Math.round(agent.maxHp)} 
                                                onChange={(e) => { const v = parseInt(e.target.value); agent.maxHp = v; agent.hp = v; setVersion(n => n + 1); }} 
                                            />
                                            <div className="h-1 bg-slate-800 mt-2 rounded overflow-hidden">
                                                <div className="h-full bg-green-500" style={{width: `${(agent.hp/agent.maxHp)*100}%`}}></div>
                                            </div>
                                        </div>
                                        <div className="bg-slate-900 p-3 rounded border border-slate-800">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-2">魔力值</label>
                                            <input 
                                                type="number" 
                                                className="tactical-input h-12 w-full text-2xl text-center text-blue-400 font-mono bg-black/30 border-blue-900/50 focus:border-blue-500"
                                                value={Math.round(agent.maxMp)} 
                                                onChange={(e) => { agent.maxMp = parseInt(e.target.value); setVersion(n => n + 1); }} 
                                            />
                                            <div className="h-1 bg-slate-800 mt-2 rounded overflow-hidden">
                                                <div className="h-full bg-blue-500" style={{width: `${(agent.mp/agent.maxMp)*100}%`}}></div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="border-t border-slate-800 pt-4">
                                    <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">技能組</div>
                                    <div className="space-y-4">
                                        {['ULT', 'ACTIVE', 'BASIC'].map((tag, i) => {
                                            const currentSkillId = agent.skillIds[i];
                                            const currentSkill = db.find(s => s.id === currentSkillId);

                                            // Available skills Logic
                                            const availableSkills = db.filter(s => s.tag === tag);
                                            const skillsByRole: Record<string, Skill[]> = {};
                                            availableSkills.forEach(s => {
                                                if(!skillsByRole[s.role]) skillsByRole[s.role] = [];
                                                skillsByRole[s.role].push(s);
                                            });
                                            const roleOrder = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

                                            return (
                                                <div key={i} className="bg-slate-900 rounded-sm border border-slate-700 shadow-md transition-all hover:border-slate-500" onMouseEnter={() => onHoverSkill && onHoverSkill(currentSkill || null)} onMouseLeave={() => onHoverSkill && onHoverSkill(null)}>
                                                    <div className="flex items-center gap-3 p-3 bg-slate-800/50 border-b border-slate-800">
                                                        <SkillIcon skill={currentSkill} className="w-12 h-12" />
                                                        <div className="flex-1">
                                                            <div className="text-[10px] font-bold text-slate-500 mb-1 flex justify-between">
                                                                <span>{TAG_MAP[tag]} 欄位</span>
                                                                {currentSkill && <span className="text-slate-400 font-mono">ID: {currentSkill.id}</span>}
                                                            </div>
                                                            <select 
                                                                className={`tactical-input h-10 w-full text-sm font-bold appearance-none cursor-pointer ${!currentSkillId ? 'text-slate-500' : 'text-slate-200'}`}
                                                                value={agent.skillIds[i] || ""} 
                                                                onChange={(e) => setSkill(i, e.target.value)}
                                                            >
                                                                <option value="">-- 空欄位 --</option>
                                                                {roleOrder.map(role => {
                                                                    const skills = skillsByRole[role];
                                                                    if (!skills || skills.length === 0) return null;
                                                                    return (
                                                                        <optgroup key={role} label={ROLE_MAP[role]} className="bg-slate-900 text-slate-400">
                                                                            {skills.map(s => (
                                                                                <option key={s.id} value={s.id} className="text-white">
                                                                                    {s.name} {s.team !== undefined ? (s.team === Team.BLUE ? '🔵' : '🔴') : ''}
                                                                                </option>
                                                                            ))}
                                                                        </optgroup>
                                                                    );
                                                                })}
                                                            </select>
                                                        </div>
                                                    </div>

                                                    {currentSkill && (
                                                        <div className="p-3 text-sm">
                                                            <div className="text-slate-400 italic mb-3 leading-relaxed border-l-2 border-slate-700 pl-3">
                                                                "{currentSkill.desc}"
                                                            </div>
                                                            <div className="grid grid-cols-4 gap-2 text-xs font-mono text-slate-300">
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">威力</div>
                                                                    <div className="font-bold text-base">{currentSkill.power}</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">冷卻</div>
                                                                    <div className="font-bold text-base">{currentSkill.cd}s</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">消耗</div>
                                                                    <div className="font-bold text-base text-blue-400">{currentSkill.cost}</div>
                                                                </div>
                                                                <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                                    <div className="text-slate-500 text-[10px] mb-1">射程</div>
                                                                    <div className="font-bold text-base">{currentSkill.range}</div>
                                                                </div>
                                                            </div>
                                                            {(currentSkill.ccType || currentSkill.effectType) && (
                                                                <div className="mt-3 pt-2 border-t border-slate-800 flex gap-2 flex-wrap">
                                                                    {currentSkill.ccType && <span className="px-2 py-1 bg-amber-900/30 text-amber-400 border border-amber-900/50 rounded text-xs font-bold">{currentSkill.ccType}</span>}
                                                                    {currentSkill.effectType && <span className="px-2 py-1 bg-purple-900/30 text-purple-400 border border-purple-900/50 rounded text-xs font-bold">{currentSkill.effectType}</span>}
                                                                </div>
                                                            )}
                                                        </div>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* TAB CONTENT: AI */}
                        {inspectorSubTab === 'AI' && (
                             <div 
                                className="flex-1 bg-[#0f1115] relative overflow-hidden flex flex-col min-h-0 cursor-grab active:cursor-grabbing" 
                                ref={btContainerRef} 
                                onWheel={handleBtWheel} 
                                onMouseDown={handleBtMouseDown} 
                                onMouseMove={handleBtMouseMove} 
                                onMouseUp={handleBtMouseUp} 
                                onMouseLeave={handleBtMouseUp}
                                onTouchStart={handleBtTouchStart}
                                onTouchMove={handleBtTouchMove}
                                onTouchEnd={handleBtTouchEnd}
                                style={{touchAction: 'none'}}
                             >
                                <div className="absolute top-4 left-4 z-10 glass-panel px-3 py-2 flex items-center gap-3">
                                    <div className="text-xs font-bold text-slate-400 uppercase">刷新率</div>
                                    <input type="range" min="1" max="60" value={btFps} onChange={e => setBtFps(parseInt(e.target.value))} className="w-24 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
                                    <span className="text-cyan-400 font-mono text-xs w-6 text-right">{btFps}</span>
                                </div>

                                <div className="absolute top-4 right-4 z-10 glass-panel px-3 py-2 text-xs font-mono text-slate-400">
                                    縮放: {Math.round(btScale * 100)}%
                                </div>

                                <div className="absolute w-full h-full flex justify-center items-start pt-20 pb-20 origin-top-center will-change-transform" 
                                     style={{
                                         transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                                         backgroundImage: 'radial-gradient(#334155 1px, transparent 1px)', 
                                         backgroundSize: '32px 32px'
                                     }}>
                                    <div id="bt-root-content" className="inline-block px-12 pb-12">
                                        {agent.bt && <TreeNode node={agent.bt} version={version} now={Date.now()} />}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                ))}

                {tab === 'LOG' && (
                    <div className="flex flex-col h-full bg-slate-900">
                        <div className="p-3 border-b border-slate-800 bg-slate-950 flex justify-between items-center shrink-0">
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">即時戰況 (最近100筆)</span>
                            <button onClick={downloadLogs} className="tactical-btn text-xs">
                                匯出 JSON
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 pb-24 font-mono">
                            {localLogs.slice().reverse().map(log => (
                                <LogItem key={log.id} log={log} />
                            ))}
                            {localLogs.length === 0 && <div className="text-slate-600 text-center mt-20 italic">尚無戰鬥紀錄</div>}
                        </div>
                    </div>
                )}

                {tab === 'DB' && (
                    <div className="flex flex-col h-full bg-slate-900">
                        <div className="p-3 border-b border-slate-800 bg-slate-950 shrink-0 space-y-3">
                            <div className="flex bg-slate-900 rounded p-1 gap-1 border border-slate-800">
                                {['ALL', 'BASIC', 'ACTIVE', 'ULT'].map(t => (
                                    <button 
                                        key={t}
                                        onClick={() => setDbTypeTab(t as any)} 
                                        className={`flex-1 py-2 text-xs rounded font-bold transition-all ${dbTypeTab === t ? 'bg-slate-800 text-cyan-400 shadow-sm border border-slate-700' : 'text-slate-500 hover:text-slate-300'}`}
                                    >
                                        {t === 'ALL' ? '全部' : TAG_MAP[t]}
                                    </button>
                                ))}
                            </div>

                            <select 
                                className="tactical-input w-full h-10 text-sm"
                                value={dbRoleFilter}
                                onChange={(e) => setDbRoleFilter(e.target.value as any)}
                            >
                                <option value="ALL">篩選職階: 全部</option>
                                {Object.values(Role).map(r => <option key={r} value={r}>職階: {ROLE_MAP[r]}</option>)}
                            </select>
                        </div>

                        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 pb-24 space-y-2">
                            {filteredSkills.map(skill => (
                                <div key={skill.id} className={`border rounded transition-all duration-200 ${selectedSkillId === skill.id ? 'border-cyan-500 bg-slate-800 shadow-lg' : 'border-slate-800 bg-slate-900 hover:border-slate-600'}`}>
                                    <div 
                                        className="flex items-center gap-3 p-3 cursor-pointer"
                                        onClick={() => setSelectedSkillId(skill.id === selectedSkillId ? null : skill.id)}
                                    >
                                        <SkillIcon skill={skill} />
                                        <div className="flex-1 min-w-0">
                                            <div className="font-bold text-sm text-slate-200">{skill.name}</div>
                                            <div className="text-xs text-slate-500 flex gap-2 items-center mt-1">
                                                <span className="font-mono font-bold">{ROLE_MAP[skill.role]}</span>
                                                <span className="w-1 h-1 bg-slate-600 rounded-full"></span>
                                                <span className={`${skill.tag === 'ULT' ? 'text-purple-400' : (skill.tag === 'ACTIVE' ? 'text-blue-400' : 'text-slate-400')} font-bold`}>{TAG_MAP[skill.tag]}</span>
                                            </div>
                                        </div>
                                        <div className="text-slate-600 text-lg">
                                            {selectedSkillId === skill.id ? '−' : '+'}
                                        </div>
                                    </div>

                                    {selectedSkillId === skill.id && (
                                        <div className="p-4 border-t border-slate-700 bg-black/20 text-left">
                                            {SKILL_FIELD_GROUPS.map((group) => (
                                                <div key={group.name} className="mb-4 last:mb-0">
                                                    <div className="text-[10px] font-bold text-slate-500 uppercase border-b border-slate-700 mb-2 pb-1">
                                                        {group.name}
                                                    </div>
                                                    <div className="grid grid-cols-2 gap-2">
                                                        {group.fields.map((field) => {
                                                            const val = (skill as any)[field.key];

                                                            // Helper for special handling of Team Enum
                                                            let displayVal = val;
                                                            if (field.key === 'team') {
                                                                if (val === undefined) displayVal = 'ANY';
                                                                else if (val === Team.BLUE) displayVal = 'BLUE';
                                                                else if (val === Team.RED) displayVal = 'RED';
                                                            } else if (val === undefined || val === null) {
                                                                displayVal = '';
                                                            }

                                                            const isWide = field.type === 'textarea';

                                                            return (
                                                                <div key={field.key} className={isWide ? "col-span-2 space-y-1" : "space-y-1"}>
                                                                    <label className="text-[9px] font-bold text-slate-500 block truncate" title={field.label}>{field.label}</label>

                                                                    {field.type === 'textarea' ? (
                                                                        <textarea 
                                                                            className="tactical-input w-full p-2 h-20 text-sm resize-none"
                                                                            value={displayVal}
                                                                            onChange={e => updateSkill(field.key, e.target.value)}
                                                                        />
                                                                    ) : field.type === 'select' ? (
                                                                        <select 
                                                                            className="tactical-input w-full h-8 text-xs appearance-none cursor-pointer"
                                                                            value={displayVal}
                                                                            onChange={e => {
                                                                                const v = e.target.value;
                                                                                if (v === 'NONE' || v === 'ANY' || v === '') updateSkill(field.key, undefined);
                                                                                else updateSkill(field.key, v); // Handled by updateSkill special logic for Team
                                                                            }}
                                                                        >
                                                                            {field.options?.map(opt => (
                                                                                <option key={opt} value={opt}>{opt}</option>
                                                                            ))}
                                                                        </select>
                                                                    ) : field.type === 'color' ? (
                                                                        <div className="flex gap-1 items-center">
                                                                            <input 
                                                                                type="text" 
                                                                                className="tactical-input flex-1 h-8 text-xs min-w-0" 
                                                                                value={displayVal} 
                                                                                onChange={e => updateSkill(field.key, e.target.value)} 
                                                                            />
                                                                            <input 
                                                                                type="color" 
                                                                                className="w-6 h-8 p-0 border-0 bg-transparent cursor-pointer" 
                                                                                value={displayVal.startsWith('#') ? displayVal : '#ffffff'} 
                                                                                onChange={e => updateSkill(field.key, e.target.value)} 
                                                                            />
                                                                        </div>
                                                                    ) : (
                                                                        <input 
                                                                            type={field.type} 
                                                                            className="tactical-input w-full h-8 text-xs"
                                                                            value={displayVal}
                                                                            step={field.step || 1}
                                                                            onChange={e => updateSkill(field.key, field.type === 'number' ? parseFloat(e.target.value) : e.target.value)}
                                                                        />
                                                                    )}
                                                                </div>
                                                            );
                                                        })}
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default InspectorPanel;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false); // Mobile Only State

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.9) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
    // Auto-open mobile inspector when unit selected
    if (agent && window.innerWidth < 1024) {
        setShowMobileInspector(true);
    }
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* FLOATING HUD (Top Center) - Z-Index 30 */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-30 transition-all duration-500 w-auto max-w-[95%] pointer-events-none ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-center gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg pointer-events-auto">

                {/* Control Group */}
                <div className="flex items-center gap-3">
                    <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Speed Control - Hidden on small screens */}
                <div className="hidden xl:flex flex-1 flex-col items-center min-w-[120px]">
                    <div className="flex items-center justify-between w-full mb-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                        <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                    </div>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                    />
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Mobile Inspector Toggle */}
                <button 
                    onClick={() => setShowMobileInspector(!showMobileInspector)}
                    className={`lg:hidden w-10 h-10 rounded-full flex items-center justify-center border transition-all ${showMobileInspector ? 'bg-cyan-900/50 border-cyan-500 text-cyan-400' : 'bg-slate-800 border-slate-600 text-slate-400'}`}
                >
                    ℹ️
                </button>

                {/* Mode Switch (Desktop Only) */}
                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="hidden lg:flex px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all items-center gap-2"
                >
                    <span>📺</span>
                    <span>展示模式</span>
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-transparent to-black/40 pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in px-4">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>初始化指揮系統</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock */}
          {/* CRITICAL FIX: flex-1, min-w-0, min-h-0 to ensure it shrinks properly in flex container */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK - Z-Index 30 */}
                <div className={`h-40 bg-slate-950 border-t border-slate-800 shrink-0 z-30 flex overflow-x-auto transition-all duration-500 ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* ZONE 1: COMMAND TOOLS */}
                    <div className="w-40 md:w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">指揮工具</div>
                        <div className="grid grid-cols-2 gap-2 flex-1">
                            <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                <span className="text-lg">⌖</span>
                                <span className="text-[9px]">選取</span>
                            </button>
                            <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                <span className="text-lg">❌</span>
                                <span className="text-[9px]">移除</span>
                            </button>
                            <button onClick={() => setTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                <span className="flex items-center gap-2">
                                    <span className="text-lg">🧱</span>
                                    <span className="text-[9px]">地形</span>
                                </span>
                            </button>
                        </div>
                        {tool === ToolType.OBSTACLE && (
                            <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        )}
                    </div>

                    {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                    <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                            <span>單位部署</span>
                            <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                        </div>

                        <div className="flex gap-4 h-full">
                            {/* Team Selectors (Sets Tool) */}
                            <div className="flex flex-col gap-2 w-28 shrink-0">
                                <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">藍隊</span>
                                    <span className="text-lg">🔵</span>
                                </button>
                                <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                    <span className="font-bold text-xs">紅隊</span>
                                    <span className="text-lg">🔴</span>
                                </button>
                            </div>

                            {/* Mode & Draft Config */}
                            <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                    <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        🎲 隨機
                                    </button>
                                    <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                        📝 自選
                                    </button>
                                </div>

                                <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                    {spawnMode === 'RANDOM' ? (
                                        <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                            <span className="text-2xl mb-1">🎲</span>
                                            <span>隨機職階</span>
                                        </div>
                                    ) : (
                                        <div className="flex gap-1.5 w-full justify-center">
                                            {Object.values(Role).map(role => (
                                                <button 
                                                    key={role}
                                                    onClick={() => setDraftRole(role)}
                                                    className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                    title={role}
                                                >
                                                    <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* HP Pool */}
                            <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                <input 
                                    type="number" 
                                    value={hpInput} 
                                    onChange={e => setHpInput(parseInt(e.target.value))} 
                                    className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                />
                            </div>
                        </div>
                    </div>

                    {/* ZONE 3: MAP OPS */}
                    <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                        <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                        <div className="grid grid-cols-2 gap-2">
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">寬度</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                            </div>
                            <div className="flex flex-col">
                                <label className="text-[8px] text-slate-500">高度</label>
                                <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                            </div>
                        </div>
                        <div className="flex gap-2 mt-auto">
                            <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                            <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空</button>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {!isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay */}
          <div 
            className={`
                flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300
                ${/* MOBILE MODE: Overlay */ ''}
                ${window.innerWidth < 1024 ? 'fixed inset-0 lg:static' : 'relative h-full'}
                ${/* VISIBILITY LOGIC */ ''}
                ${window.innerWidth < 1024 && !showMobileInspector ? 'pointer-events-none opacity-0 translate-x-full lg:pointer-events-auto lg:opacity-100 lg:translate-x-0' : 'opacity-100 translate-x-0'}
                ${/* SHOWCASE MODE: Hide completely on desktop */ ''}
                ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
            `}
            style={{ width: (window.innerWidth >= 1024 && !isShowcaseMode) ? sidebarWidth : undefined }}
          >
            {/* Mobile Header for Close */}
            <div className="lg:hidden p-3 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0">
                 <h3 className="font-bold text-slate-200">單位監控面板</h3>
                 <button onClick={() => setShowMobileInspector(false)} className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded text-slate-400">✕</button>
            </div>

            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false); // Mobile Only State

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.9) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
    // Auto-open mobile inspector when unit selected
    if (agent && window.innerWidth < 1024) {
        setShowMobileInspector(true);
    }
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* FLOATING HUD (Top Center) - Z-Index 30 */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-30 transition-all duration-500 w-auto max-w-[95%] pointer-events-none ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-center gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg pointer-events-auto">

                {/* Control Group */}
                <div className="flex items-center gap-3">
                    <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Speed Control - Hidden on small screens */}
                <div className="hidden xl:flex flex-1 flex-col items-center min-w-[120px]">
                    <div className="flex items-center justify-between w-full mb-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                        <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                    </div>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                    />
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Mode Switch (Desktop Only) */}
                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="hidden lg:flex px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all items-center gap-2"
                >
                    <span>📺</span>
                    <span>展示模式</span>
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-transparent to-black/40 pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in px-4">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>初始化指揮系統</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock */}
          {/* CRITICAL FIX: flex-1, min-w-0, min-h-0 to ensure it shrinks properly in flex container */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                <div className={`bg-slate-950 border-t border-slate-800 shrink-0 z-30 transition-all duration-500 w-full ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* MOBILE GRID LAYOUT (< md) */}
                    <div className="md:hidden grid grid-cols-4 gap-2 p-2">
                        {/* Row 1: Primary Tools */}
                        <button 
                            onClick={() => setTool(ToolType.SELECT)} 
                            className={`h-10 tactical-btn ${tool === ToolType.SELECT ? 'active' : ''}`}
                        >
                            <span className="text-lg">⌖</span>
                        </button>

                        <button 
                            onClick={() => setTool(ToolType.ADD_BLUE)} 
                            className={`h-10 tactical-btn btn-blue ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-70'}`}
                        >
                            <span className="text-lg">🔵</span>
                        </button>

                        <button 
                            onClick={() => setTool(ToolType.ADD_RED)} 
                            className={`h-10 tactical-btn btn-red ${tool === ToolType.ADD_RED ? 'active' : 'opacity-70'}`}
                        >
                            <span className="text-lg">🔴</span>
                        </button>

                        <button 
                            onClick={() => setTool(ToolType.DELETE)} 
                            className={`h-10 tactical-btn text-red-400 border-red-900/50 ${tool === ToolType.DELETE ? 'active bg-red-950/50 border-red-500' : ''}`}
                        >
                            <span className="text-lg">❌</span>
                        </button>

                        {/* Row 2: Secondary Tools */}
                        <div className={`col-span-2 flex items-center bg-slate-900 border border-slate-700 rounded-sm h-10 px-1 ${tool === ToolType.OBSTACLE ? 'border-cyan-500' : ''}`}>
                            <button 
                                onClick={() => setTool(ToolType.OBSTACLE)}
                                className={`h-full w-10 flex items-center justify-center shrink-0 hover:bg-slate-800 ${tool === ToolType.OBSTACLE ? 'text-cyan-400' : 'text-slate-400'}`}
                            >
                                <span className="text-lg">🧱</span>
                            </button>
                            <select 
                                className="w-full bg-transparent text-[10px] text-slate-300 outline-none h-full"
                                value={selectedObstacle} 
                                onChange={e => setSelectedObstacle(e.target.value)}
                            >
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id} className="bg-slate-900">{o.name}</option>)}
                            </select>
                        </div>

                        <div className="col-span-1 min-w-0">
                            <div className="h-10 w-full flex items-center justify-center bg-slate-800 border border-slate-700 rounded-sm">
                                <span className="text-[8px] text-slate-500 absolute -mt-6">HP</span>
                                <input 
                                    type="number" 
                                    value={hpInput} 
                                    onChange={e => setHpInput(parseInt(e.target.value))} 
                                    className="w-full h-full bg-transparent text-center text-xs font-mono text-slate-200 outline-none"
                                />
                            </div>
                        </div>

                        <div className="col-span-1">
                            <button 
                                onClick={() => setShowMobileInspector(!showMobileInspector)}
                                className={`h-10 w-full tactical-btn ${showMobileInspector ? 'active' : ''}`}
                            >
                                <span className="text-lg">⚙️</span>
                            </button>
                        </div>
                    </div>

                    {/* DESKTOP FLEX LAYOUT (>= md) */}
                    <div className="hidden md:flex h-40 overflow-x-auto overflow-y-hidden">

                        {/* ZONE 1: COMMAND TOOLS */}
                        <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">指揮工具</div>
                            <div className="grid grid-cols-2 gap-2 flex-1">
                                <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                    <span className="text-lg">⌖</span>
                                    <span className="text-[9px]">選取</span>
                                </button>
                                <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                    <span className="text-lg">❌</span>
                                    <span className="text-[9px]">移除</span>
                                </button>
                                <button onClick={() => setTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                    <span className="flex items-center gap-2">
                                        <span className="text-lg">🧱</span>
                                        <span className="text-[9px]">地形</span>
                                    </span>
                                </button>
                            </div>
                            {tool === ToolType.OBSTACLE && (
                                <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                    {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                </select>
                            )}
                        </div>

                        {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                        <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                                <span>單位部署</span>
                                <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                            </div>

                            <div className="flex gap-4 h-full">
                                {/* Team Selectors (Sets Tool) */}
                                <div className="flex flex-col gap-2 w-28 shrink-0">
                                    <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">藍隊</span>
                                        <span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">紅隊</span>
                                        <span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                {/* Mode & Draft Config */}
                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                    <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            🎲 隨機
                                        </button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            📝 自選
                                        </button>
                                    </div>

                                    <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                        {spawnMode === 'RANDOM' ? (
                                            <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                                <span className="text-2xl mb-1">🎲</span>
                                                <span>隨機職階</span>
                                            </div>
                                        ) : (
                                            <div className="flex gap-1.5 w-full justify-center">
                                                {Object.values(Role).map(role => (
                                                    <button 
                                                        key={role}
                                                        onClick={() => setDraftRole(role)}
                                                        className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                        title={role}
                                                    >
                                                        <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* HP Pool */}
                                <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                    <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                    <input 
                                        type="number" 
                                        value={hpInput} 
                                        onChange={e => setHpInput(parseInt(e.target.value))} 
                                        className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ZONE 3: MAP OPS */}
                        <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">寬度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                </div>
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">高度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {!isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay */}
          <div 
            className={`
                flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300
                ${/* MOBILE MODE: Overlay */ ''}
                ${window.innerWidth < 1024 ? 'fixed inset-0 lg:static' : 'relative h-full'}
                ${/* VISIBILITY LOGIC */ ''}
                ${window.innerWidth < 1024 && !showMobileInspector ? 'pointer-events-none opacity-0 translate-x-full lg:pointer-events-auto lg:opacity-100 lg:translate-x-0' : 'opacity-100 translate-x-0'}
                ${/* SHOWCASE MODE: Hide completely on desktop */ ''}
                ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
            `}
            style={{ width: (window.innerWidth >= 1024 && !isShowcaseMode) ? sidebarWidth : undefined }}
          >
            {/* Mobile Header for Close */}
            <div className="lg:hidden p-3 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0">
                 <h3 className="font-bold text-slate-200">單位監控面板</h3>
                 <button onClick={() => setShowMobileInspector(false)} className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded text-slate-400">✕</button>
            </div>

            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false); // Mobile Only State
  const [showMapSettings, setShowMapSettings] = useState(false); // Mobile Map Modal

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.9) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
    // Removed auto-inspector logic to fix drag conflict
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* FLOATING HUD (Top Center) - Z-Index 30 */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-30 transition-all duration-500 w-auto max-w-[95%] pointer-events-none ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-center gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg pointer-events-auto">

                {/* Control Group */}
                <div className="flex items-center gap-3">
                    <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Speed Control - Hidden on small screens */}
                <div className="hidden xl:flex flex-1 flex-col items-center min-w-[120px]">
                    <div className="flex items-center justify-between w-full mb-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                        <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                    </div>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                    />
                </div>

                {/* Mode Switch (Desktop Only) */}
                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="hidden lg:flex px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all items-center gap-2"
                >
                    <span>📺</span>
                    <span>展示模式</span>
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* MAP SETTINGS MODAL (Mobile Only) */}
      {showMapSettings && (
        <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center bg-black/50 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setShowMapSettings(false)}>
            <div className="bg-slate-900 border border-slate-700 p-4 rounded-xl shadow-2xl w-full max-w-sm space-y-4 mb-32 sm:mb-0 pointer-events-auto" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center border-b border-slate-800 pb-2">
                    <h3 className="font-bold text-slate-300">地圖設定</h3>
                    <button onClick={() => setShowMapSettings(false)} className="text-slate-500 hover:text-slate-300 w-8 h-8 flex items-center justify-center">✕</button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">寬度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapW} onChange={e=>setMapW(Number(e.target.value))} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">高度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapH} onChange={e=>setMapH(Number(e.target.value))} />
                    </div>
                </div>
                <div className="flex gap-3 pt-2">
                    <button onClick={() => { updateMap(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 border-slate-600 hover:bg-slate-800">重建地圖</button>
                    <button onClick={() => { handleClear(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                </div>
            </div>
        </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-transparent to-black/40 pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in px-4">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>初始化指揮系統</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock */}
          {/* CRITICAL FIX: flex-1, min-w-0, min-h-0 to ensure it shrinks properly in flex container */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                <div className={`bg-slate-950 border-t border-slate-800 shrink-0 z-30 transition-all duration-500 w-full ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* MOBILE GRID LAYOUT (< md) - 2x4 GRID */}
                    <div className="md:hidden grid grid-cols-4 gap-2 p-2 h-auto">
                        {/* Row 1: Primary Actions */}
                        <button onClick={() => setTool(ToolType.SELECT)} className={`h-10 tactical-btn ${tool === ToolType.SELECT ? 'active' : ''}`}>
                            <span className="text-lg">⌖</span>
                        </button>

                        <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`h-10 tactical-btn btn-blue ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-70'}`}>
                            <span className="text-lg">🔵</span>
                        </button>

                        <button onClick={() => setTool(ToolType.ADD_RED)} className={`h-10 tactical-btn btn-red ${tool === ToolType.ADD_RED ? 'active' : 'opacity-70'}`}>
                            <span className="text-lg">🔴</span>
                        </button>

                        <button onClick={() => setTool(ToolType.DELETE)} className={`h-10 tactical-btn text-red-400 border-red-900/50 ${tool === ToolType.DELETE ? 'active bg-red-950/50 border-red-500' : ''}`}>
                            <span className="text-lg">❌</span>
                        </button>

                        {/* Row 2: Secondary & Config */}
                        {/* Slot 5: Obstacle Tool + Dropdown Overlay */}
                        <div className={`relative h-10 tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active border-cyan-500' : ''}`}>
                            <button onClick={() => setTool(ToolType.OBSTACLE)} className="w-full h-full flex items-center justify-center gap-1">
                                <span className="text-lg">🧱</span>
                                <span className="text-[8px] absolute bottom-0.5 right-1 opacity-50">▼</span>
                            </button>
                            <select 
                                className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                value={selectedObstacle} 
                                onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}
                            >
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        </div>

                        {/* Slot 6: HP Input */}
                        <div className="h-10 flex items-center justify-center bg-slate-900 border border-slate-700 rounded-sm relative">
                            <span className="text-[8px] text-slate-500 absolute -top-1.5 left-1 bg-slate-900 px-0.5">HP</span>
                            <input 
                                type="number" 
                                value={hpInput} 
                                onChange={e => setHpInput(parseInt(e.target.value))} 
                                className="w-full h-full bg-transparent text-center text-xs font-mono text-slate-200 outline-none"
                            />
                        </div>

                        {/* Slot 7: Map Settings Toggle */}
                        <button 
                            onClick={() => setShowMapSettings(!showMapSettings)}
                            className={`h-10 tactical-btn ${showMapSettings ? 'border-cyan-500 text-cyan-400' : ''}`}
                        >
                            <span className="text-lg">🗺️</span>
                        </button>

                        {/* Slot 8: Inspect Toggle */}
                        <button 
                            onClick={() => selectedAgent && setShowMobileInspector(!showMobileInspector)}
                            disabled={!selectedAgent}
                            className={`h-10 tactical-btn ${showMobileInspector ? 'active' : ''} ${selectedAgent ? 'border-blue-500/50 text-blue-300 animate-pulse-glow' : 'opacity-30'}`}
                        >
                            <span className="text-lg">👁️</span>
                        </button>
                    </div>

                    {/* DESKTOP FLEX LAYOUT (>= md) */}
                    <div className="hidden md:flex h-40 overflow-x-auto overflow-y-hidden">

                        {/* ZONE 1: COMMAND TOOLS */}
                        <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">指揮工具</div>
                            <div className="grid grid-cols-2 gap-2 flex-1">
                                <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                    <span className="text-lg">⌖</span>
                                    <span className="text-[9px]">選取</span>
                                </button>
                                <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                    <span className="text-lg">❌</span>
                                    <span className="text-[9px]">移除</span>
                                </button>
                                <button onClick={() => setTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                    <span className="flex items-center gap-2">
                                        <span className="text-lg">🧱</span>
                                        <span className="text-[9px]">地形</span>
                                    </span>
                                </button>
                            </div>
                            {tool === ToolType.OBSTACLE && (
                                <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                    {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                </select>
                            )}
                        </div>

                        {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                        <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                                <span>單位部署</span>
                                <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                            </div>

                            <div className="flex gap-4 h-full">
                                {/* Team Selectors (Sets Tool) */}
                                <div className="flex flex-col gap-2 w-28 shrink-0">
                                    <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">藍隊</span>
                                        <span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">紅隊</span>
                                        <span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                {/* Mode & Draft Config */}
                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                    <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            🎲 隨機
                                        </button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            📝 自選
                                        </button>
                                    </div>

                                    <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                        {spawnMode === 'RANDOM' ? (
                                            <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                                <span className="text-2xl mb-1">🎲</span>
                                                <span>隨機職階</span>
                                            </div>
                                        ) : (
                                            <div className="flex gap-1.5 w-full justify-center">
                                                {Object.values(Role).map(role => (
                                                    <button 
                                                        key={role}
                                                        onClick={() => setDraftRole(role)}
                                                        className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                        title={role}
                                                    >
                                                        <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* HP Pool */}
                                <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                    <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                    <input 
                                        type="number" 
                                        value={hpInput} 
                                        onChange={e => setHpInput(parseInt(e.target.value))} 
                                        className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ZONE 3: MAP OPS */}
                        <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">寬度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                </div>
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">高度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {!isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay */}
          <div 
            className={`
                flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300
                ${/* MOBILE MODE: Overlay */ ''}
                ${window.innerWidth < 1024 ? 'fixed inset-0 lg:static' : 'relative h-full'}
                ${/* VISIBILITY LOGIC */ ''}
                ${window.innerWidth < 1024 && !showMobileInspector ? 'pointer-events-none opacity-0 translate-x-full lg:pointer-events-auto lg:opacity-100 lg:translate-x-0' : 'opacity-100 translate-x-0'}
                ${/* SHOWCASE MODE: Hide completely on desktop */ ''}
                ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
            `}
            style={{ width: (window.innerWidth >= 1024 && !isShowcaseMode) ? sidebarWidth : undefined }}
          >
            {/* Mobile Header for Close */}
            <div className="lg:hidden p-3 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0">
                 <h3 className="font-bold text-slate-200">單位監控面板</h3>
                 <button onClick={() => setShowMobileInspector(false)} className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded text-slate-400">✕</button>
            </div>

            <InspectorPanel 
                agent={selectedAgent} 
                engine={engineRef.current}
                logs={[]} 
                db={engineRef.current.skillDB}
                onHoverSkill={setHoveredSkill}
            />
          </div>
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false); 
  const [showMapSettings, setShowMapSettings] = useState(false);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(400);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Logic Impl ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  const startResizing = useCallback(() => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const resize = useCallback((e: MouseEvent) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - e.clientX;
          if (newWidth > 300 && newWidth < window.innerWidth * 0.9) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  useEffect(() => {
      window.addEventListener('mousemove', resize);
      window.addEventListener('mouseup', stopResizing);
      return () => {
          window.removeEventListener('mousemove', resize);
          window.removeEventListener('mouseup', stopResizing);
      };
  }, [resize, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  return (
    // APP SHELL: Fixed Viewport Height, Flex Column
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none">

      {/* 1. HEADER BAR (Desktop & Mobile) - Static Top */}
      <header className={`h-14 bg-slate-900 border-b border-slate-800 shrink-0 flex items-center justify-between px-3 z-30 transition-all duration-300 ${isShowcaseMode ? '-mt-14' : 'mt-0'}`}>

          {/* Logo / Home */}
          <div className="flex items-center gap-4">
              <button 
                  onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                  className="font-bold text-lg tracking-tight text-cyan-400 hover:text-white flex items-center gap-2"
              >
                  <span className="text-xl">⚔️</span>
                  <span className="hidden md:inline">TACTICAL<span className="text-slate-500">.OS</span></span>
              </button>
              <div className="h-6 w-px bg-slate-700 hidden md:block"></div>

              {/* Playback Controls (Moved from floating HUD) */}
              <div className="flex items-center gap-2">
                  <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-8 h-8 rounded border transition-all ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-slate-800 border-slate-600 text-emerald-400 hover:bg-slate-700 hover:border-emerald-500'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
              </div>
          </div>

          {/* Center Info (Desktop) */}
          <div className="hidden md:flex items-center gap-4 text-xs font-mono text-slate-500">
                <span>UNITS: <span className="text-slate-300">{unitCount}</span></span>
                <span>|</span>
                <span>MAP: <span className="text-slate-300">{mapW}x{mapH}</span></span>
          </div>

          {/* Speed Control */}
          <div className="flex items-center gap-3">
              <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest hidden sm:inline">SPEED</span>
              <input 
                    type="range" min="0.1" max="3.0" step="0.1" 
                    value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                    className="w-24 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
              />
              <span className="text-[10px] font-mono text-cyan-400 w-8 text-right">{timeScale.toFixed(1)}x</span>
          </div>
      </header>

      {/* 2. MAIN CONTENT AREA (Flex Row) */}
      <div className="flex-1 flex overflow-hidden relative z-0 min-h-0">

          {/* LEFT: CANVAS + BOTTOM TOOLBAR */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">

                {/* CANVAS */}
                <div className="flex-1 relative min-h-0">
                    <GameCanvas 
                        engine={engineRef.current} 
                        tool={tool}
                        selectedObstacle={selectedObstacle}
                        hpInput={hpInput}
                        selectedAgent={selectedAgent}
                        hoveredSkill={hoveredSkill}
                        isShowcaseMode={isShowcaseMode}
                        spawnMode={spawnMode}
                        draftRole={draftRole}
                        onSelect={handleSelectAgent} 
                        onWin={onWin}
                        winner={winner}
                        rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                        transitionPhase={transitionPhase}
                    />

                    {/* Floating Warning (Inside Canvas Area) */}
                    {showFactionWarning && (
                        <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                            <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl backdrop-blur-sm">
                                <span className="text-xl">⚠️</span>
                                <div className="flex flex-col">
                                    <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                                    <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* BOTTOM TOOLBAR (Unified Logic, Responsive Layout) */}
                <div className={`bg-slate-950 border-t border-slate-800 shrink-0 z-30 transition-all duration-300 w-full ${isShowcaseMode ? 'translate-y-full opacity-0 h-0' : 'translate-y-0 opacity-100'}`}>

                    {/* MOBILE LAYOUT: Gamepad Grid */}
                    <div className="md:hidden grid grid-cols-4 gap-2 p-2 h-auto">
                        <button onClick={() => setTool(ToolType.SELECT)} className={`h-10 tactical-btn ${tool === ToolType.SELECT ? 'active' : ''}`}>
                            <span className="text-lg">⌖</span>
                        </button>

                        <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`h-10 tactical-btn btn-blue ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-70'}`}>
                            <span className="text-lg">🔵</span>
                        </button>

                        <button onClick={() => setTool(ToolType.ADD_RED)} className={`h-10 tactical-btn btn-red ${tool === ToolType.ADD_RED ? 'active' : 'opacity-70'}`}>
                            <span className="text-lg">🔴</span>
                        </button>

                        <button onClick={() => setTool(ToolType.DELETE)} className={`h-10 tactical-btn text-red-400 border-red-900/50 ${tool === ToolType.DELETE ? 'active bg-red-950/50 border-red-500' : ''}`}>
                            <span className="text-lg">❌</span>
                        </button>

                        {/* Row 2 */}
                        <div className={`relative h-10 tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active border-cyan-500' : ''}`}>
                            <button onClick={() => setTool(ToolType.OBSTACLE)} className="w-full h-full flex items-center justify-center gap-1">
                                <span className="text-lg">🧱</span>
                                <span className="text-[8px] absolute bottom-0.5 right-1 opacity-50">▼</span>
                            </button>
                            <select className="absolute inset-0 opacity-0 w-full h-full cursor-pointer" value={selectedObstacle} onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}>
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        </div>

                        <div className="h-10 flex items-center justify-center bg-slate-900 border border-slate-700 rounded-sm relative">
                            <span className="text-[8px] text-slate-500 absolute -top-1.5 left-1 bg-slate-900 px-0.5">HP</span>
                            <input type="number" value={hpInput} onChange={e => setHpInput(parseInt(e.target.value))} className="w-full h-full bg-transparent text-center text-xs font-mono text-slate-200 outline-none" />
                        </div>

                        <button onClick={() => setShowMapSettings(!showMapSettings)} className={`h-10 tactical-btn ${showMapSettings ? 'border-cyan-500 text-cyan-400' : ''}`}>
                            <span className="text-lg">🗺️</span>
                        </button>

                        <button onClick={() => selectedAgent && setShowMobileInspector(!showMobileInspector)} disabled={!selectedAgent} className={`h-10 tactical-btn ${showMobileInspector ? 'active' : ''} ${selectedAgent ? 'border-blue-500/50 text-blue-300 animate-pulse-glow' : 'opacity-30'}`}>
                            <span className="text-lg">👁️</span>
                        </button>
                    </div>

                    {/* DESKTOP LAYOUT: Flex Strip */}
                    <div className="hidden md:flex h-32 items-stretch">
                        {/* Zone 1: Tools */}
                        <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 bg-slate-900/50">
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">TOOLS</div>
                            <div className="grid grid-cols-2 gap-2 flex-1">
                                <button onClick={() => setTool(ToolType.SELECT)} className={`tactical-btn flex-col ${tool === ToolType.SELECT ? 'active' : ''}`}>
                                    <span className="text-lg">⌖</span><span className="text-[9px]">SELECT</span>
                                </button>
                                <button onClick={() => setTool(ToolType.DELETE)} className={`tactical-btn flex-col text-red-400 hover:border-red-500 ${tool === ToolType.DELETE ? 'active bg-red-950/30' : ''}`}>
                                    <span className="text-lg">❌</span><span className="text-[9px]">DELETE</span>
                                </button>
                                <div className="col-span-2 flex gap-1">
                                    <button onClick={() => setTool(ToolType.OBSTACLE)} className={`flex-1 tactical-btn ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>🧱</button>
                                    <select className="bg-slate-900 border border-slate-700 text-[10px] w-24 rounded px-1 outline-none text-slate-400" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                        {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                    </select>
                                </div>
                            </div>
                        </div>

                        {/* Zone 2: Deployment */}
                        <div className="flex-1 p-3 flex flex-col gap-2">
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider flex justify-between">
                                <span>DEPLOYMENT</span>
                                <span className="font-mono text-cyan-500">HP: {hpInput}</span>
                            </div>
                            <div className="flex gap-4 h-full">
                                <div className="flex flex-col gap-2 w-32">
                                    <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue px-2 justify-between ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="text-xs">BLUE</span><span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => setTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red px-2 justify-between ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="text-xs">RED</span><span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2">
                                    <div className="flex gap-2">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`px-3 py-1 text-[10px] font-bold rounded ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400' : 'text-slate-500'}`}>RANDOM</button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`px-3 py-1 text-[10px] font-bold rounded ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400' : 'text-slate-500'}`}>DRAFT</button>
                                    </div>
                                    <div className="flex-1 flex items-center justify-center border-t border-slate-800/50 mt-1 pt-1">
                                        {spawnMode === 'RANDOM' ? (
                                            <span className="text-slate-600 text-xs italic">Random Role Assignment</span>
                                        ) : (
                                            <div className="flex gap-2">
                                                {Object.values(Role).map(role => (
                                                    <button key={role} onClick={() => setDraftRole(role)} className={`w-8 h-8 rounded flex items-center justify-center border ${draftRole === role ? 'bg-amber-900/30 border-amber-500 text-amber-400' : 'bg-slate-800 border-slate-700 text-slate-500'}`}>
                                                        {roleIcons[role]}
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                <div className="flex flex-col justify-center gap-1 w-16">
                                    <label className="text-[8px] text-slate-500 text-center">HP SET</label>
                                    <input type="number" value={hpInput} onChange={e => setHpInput(parseInt(e.target.value))} className="tactical-input text-center h-8" />
                                </div>
                            </div>
                        </div>

                        {/* Zone 3: Map */}
                        <div className="w-40 border-l border-slate-800 p-3 flex flex-col gap-2 bg-slate-900/50">
                            <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">MAP OPS</div>
                            <div className="grid grid-cols-2 gap-2">
                                <input type="number" className="tactical-input p-1 text-center h-8 text-xs" placeholder="W" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                <input type="number" className="tactical-input p-1 text-center h-8 text-xs" placeholder="H" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-1">BUILD</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-1 text-red-400 border-red-900">CLEAR</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT: INSPECTOR (Desktop: Sidebar, Mobile: Modal) */}
          {/* DESKTOP SIDEBAR */}
          {!isShowcaseMode && (
            <>
                <div 
                    className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                    onMouseDown={startResizing}
                >
                    <div className="w-[1px] h-8 bg-slate-600"></div>
                </div>
                <div 
                    className={`hidden lg:flex flex-col z-40 shadow-2xl bg-slate-950 border-l border-slate-800 transition-all duration-300 ${isShowcaseMode ? 'w-0 border-none' : ''}`}
                    style={{ width: isShowcaseMode ? 0 : sidebarWidth }}
                >
                    <InspectorPanel agent={selectedAgent} engine={engineRef.current} logs={[]} db={engineRef.current.skillDB} onHoverSkill={setHoveredSkill} />
                </div>
            </>
          )}

          {/* MOBILE MODAL INSPECTOR */}
          {/* Uses a full-screen overlay style but keeps context */}
          <div className={`lg:hidden fixed inset-0 z-50 bg-slate-950 transition-transform duration-300 flex flex-col ${showMobileInspector ? 'translate-y-0' : 'translate-y-full'}`}>
                <div className="h-14 border-b border-slate-800 flex items-center justify-between px-4 bg-slate-900 shrink-0">
                    <span className="font-bold text-slate-200">UNIT INSPECTOR</span>
                    <button onClick={() => setShowMobileInspector(false)} className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded-full text-slate-400 border border-slate-700">✕</button>
                </div>
                <div className="flex-1 overflow-hidden">
                    <InspectorPanel agent={selectedAgent} engine={engineRef.current} logs={[]} db={engineRef.current.skillDB} onHoverSkill={setHoveredSkill} />
                </div>
          </div>

      </div>

      {/* MOBILE MAP SETTINGS MODAL */}
      {showMapSettings && (
        <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center bg-black/60 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setShowMapSettings(false)}>
            <div className="bg-slate-900 border border-slate-700 p-6 rounded-xl shadow-2xl w-full max-w-sm space-y-6 mb-20 sm:mb-0 pointer-events-auto" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center border-b border-slate-800 pb-4">
                    <h3 className="font-bold text-xl text-slate-200">Map Configuration</h3>
                    <button onClick={() => setShowMapSettings(false)} className="text-slate-500 hover:text-slate-300">✕</button>
                </div>
                <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <label className="text-xs text-slate-500 font-bold uppercase tracking-wider">Width</label>
                        <input type="number" className="tactical-input w-full text-center h-12 text-xl" value={mapW} onChange={e=>setMapW(Number(e.target.value))} />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs text-slate-500 font-bold uppercase tracking-wider">Height</label>
                        <input type="number" className="tactical-input w-full text-center h-12 text-xl" value={mapH} onChange={e=>setMapH(Number(e.target.value))} />
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => { updateMap(); setShowMapSettings(false); }} className="tactical-btn py-4 border-slate-600 hover:bg-slate-800 text-sm">REBUILD MAP</button>
                    <button onClick={() => { handleClear(); setShowMapSettings(false); }} className="tactical-btn py-4 text-red-400 border-red-900 hover:bg-red-950 text-sm">CLEAR UNITS</button>
                </div>
            </div>
        </div>
      )}

      {/* SHOWCASE OVERLAY (Full Cover) */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 bg-gradient-to-t from-black/90 via-slate-950/80 to-black/40 backdrop-blur-sm pointer-events-none">
                <div className="text-center pointer-events-auto animate-fade-in px-4">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.OS</span>
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">Battle Simulator v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>INITIALIZE SYSTEM</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
            </div>
      )}
    </div>
  );
}

export default App;
